import axiosLib, { type AxiosError, type AxiosRequestConfig } from 'axios';

/**
 * Standard backend envelope returned by ISA-95 APIs.
 * @template T Data payload type.
 */
export interface WrappedResponse<T> {
  success: boolean
  statusCode: number
  message?: string
  messages?: Array<string>
  data?: T
}

/**
 * Renders an unknown value as a comma-separated message string when it is a string array.
 * @param value Candidate value to render.
 * @returns Comma-separated message text, or an empty string.
 */
function renderMessages(value: unknown): string {
  if (!Array.isArray(value)) {
    return '';
  }

  return value
    .filter((item): item is string => typeof item === 'string')
    .map(item => item.trim())
    .filter(item => item.length > 0)
    .join(', ');
}

/**
 * Extracts the best available user-facing message from a backend payload object.
 * Supports wrapped envelopes (`messages[]`, `message`) and common scalar fields (`error`, `detail`).
 * @param payload Response payload to inspect.
 * @returns Parsed message when available, otherwise undefined.
 */
export function extractBackendMessage(payload: unknown): string | undefined {
  if (typeof payload === 'string' && payload.trim().length > 0) {
    return payload.trim();
  }

  if (payload === null || payload === undefined || typeof payload !== 'object') {
    return undefined;
  }

  const record = payload as Record<string, unknown>;

  const fromMessages = renderMessages(record.messages);
  if (fromMessages.length > 0) {
    return fromMessages;
  }

  const direct = record.message ?? record.error ?? record.detail;
  if (typeof direct === 'string' && direct.trim().length > 0) {
    return direct.trim();
  }

  const fromDirectArray = renderMessages(direct);
  if (fromDirectArray.length > 0) {
    return fromDirectArray;
  }

  return undefined;
}

/**
 * Resolves the best wrapped-response message, falling back when none is present.
 * @param payload Wrapped backend response.
 * @param fallback Message used when payload does not include an error message.
 * @returns User-facing error message.
 */
function getWrappedMessage(payload: WrappedResponse<unknown>, fallback: string): string {
  return extractBackendMessage(payload) ?? fallback;
}

/**
 * Checks whether the wrapped response carries a failure HTTP status code.
 * @param payload Wrapped backend response.
 * @returns True when status code is finite and >= 400.
 */
function hasFailureStatusCode(payload: WrappedResponse<unknown>): boolean {
  return Number.isFinite(payload.statusCode) && payload.statusCode >= 400;
}

/**
 * Builds authorization headers for Bearer-token authenticated requests.
 * @param token Access token value.
 * @returns Authorization headers when token exists, otherwise an empty object.
 */
export function buildBearerAuthHeaders(token?: string): Record<string, string> {
  if (token === undefined || token.length === 0) {
    return {};
  }

  return { authorization: `Bearer ${token}` };
}

/**
 * Type guard for wrapped backend responses that follow the success/statusCode/message/data contract.
 * @param payload Response payload to inspect.
 * @returns True when payload matches the WrappedResponse shape.
 */
export function isWrappedResponse<T>(payload: unknown): payload is WrappedResponse<T> {
  if (payload === null || payload === undefined || typeof payload !== 'object') {
    return false;
  }

  const candidate = payload as Record<string, unknown>;
  return (
    typeof candidate.success === 'boolean'
  );
}

/**
 * Unwraps payloads that may be wrapped by backend response metadata.
 * @param payload Wrapped or raw payload value.
 * @param fallback Message used when wrapped response indicates a failure.
 * @returns The unwrapped payload, or undefined when backend data is null.
 */
export function unwrapPayload<T>(
  payload: WrappedResponse<T | null>,
  fallback = 'Request failed.',
): T | undefined {
  if (!payload.success || hasFailureStatusCode(payload)) {
    throw new Error(getWrappedMessage(payload, fallback));
  }

  return payload.data ?? undefined;
}

/**
 * Safely normalizes array payloads from wrapped, nested, or direct array response shapes.
 * @param payload Wrapped or raw array payload.
 * @param fallback Message used when wrapped response indicates a failure.
 * @returns A normalized array value, or an empty array when data is missing.
 */
export function unwrapArrayPayload<T>(
  payload: WrappedResponse<Array<T> | null>,
  fallback = 'Request failed.',
): Array<T> {
  if (!payload.success || hasFailureStatusCode(payload)) {
    throw new Error(getWrappedMessage(payload, fallback));
  }

  return payload.data ?? [];
}

/**
 * Extracts the best available user-facing message from axios/server error payloads.
 * @param error Thrown error object.
 * @param fallback Default message used when payload-specific details are unavailable.
 * @returns Resolved error reason suitable for UI notifications.
 */
export function extractErrorReason(error: unknown, fallback: string): string {
  const axiosError = error as AxiosError;
  const responseData = axiosError?.response?.data;

  const backendMessage = extractBackendMessage(responseData);
  if (backendMessage !== undefined) {
    return backendMessage;
  }

  if (isWrappedResponse(responseData)) {
    const wrappedMessage = getWrappedMessage(responseData, '');
    if (wrappedMessage.length > 0) {
      return wrappedMessage;
    }
  }

  if (typeof responseData === 'string' && responseData.trim().length > 0) {
    return responseData;
  }

  if (responseData !== null && responseData !== undefined && typeof responseData === 'object') {
    const payload = responseData as Record<string, unknown>;
    const directMessage = payload.message ?? payload.error ?? payload.detail;

    if (Array.isArray(directMessage)) {
      const rendered = directMessage.filter((item): item is string => typeof item === 'string').join(', ').trim();
      if (rendered.length > 0) {
        return rendered;
      }
    }

    if (typeof directMessage === 'string' && directMessage.trim().length > 0) {
      return directMessage;
    }
  }

  if (error instanceof Error && error.message.trim().length > 0) {
    return error.message;
  }

  return fallback;
}

/**
 * Performs a GET request and rethrows request failures with normalized, readable messages.
 * @param url Request URL.
 * @param fallback Default message used when no server message is available.
 * @param config Optional axios request configuration.
 * @returns Response body typed as T.
 */
export async function requestGet<T>(
  url: string,
  fallback: string,
  config?: AxiosRequestConfig,
): Promise<WrappedResponse<T>> {
  let response;

  try {
    response = await axiosLib.get<WrappedResponse<T>>(url, config);
  }
  catch (error) {
    throw new Error(extractErrorReason(error, fallback));
  }

  if (!isWrappedResponse<T>(response.data)) {
    throw new Error(extractBackendMessage(response.data) ?? fallback);
  }

  return response.data;
}

/**
 * Performs a POST request and rethrows request failures with normalized, readable messages.
 * @param url Request URL.
 * @param payload Body payload sent with the request.
 * @param fallback Default message used when no server message is available.
 * @param config Optional axios request configuration.
 * @returns Response body typed as T.
 */
export async function requestPost<T>(
  url: string,
  payload: unknown,
  fallback: string,
  config?: AxiosRequestConfig,
): Promise<WrappedResponse<T>> {
  let response;

  try {
    response = await axiosLib.post<WrappedResponse<T>>(url, payload, config);
  }
  catch (error) {
    throw new Error(extractErrorReason(error, fallback));
  }

  if (!isWrappedResponse<T>(response.data)) {
    throw new Error(extractBackendMessage(response.data) ?? fallback);
  }

  return response.data;
}

/**
 * Performs a PATCH request and rethrows request failures with normalized, readable messages.
 * @param url Request URL.
 * @param payload Partial body payload sent with the request.
 * @param fallback Default message used when no server message is available.
 * @param config Optional axios request configuration.
 * @returns Response body typed as T.
 */
export async function requestPatch<T>(
  url: string,
  payload: unknown,
  fallback: string,
  config?: AxiosRequestConfig,
): Promise<WrappedResponse<T>> {
  let response;

  try {
    response = await axiosLib.patch<WrappedResponse<T>>(url, payload, config);
  }
  catch (error) {
    throw new Error(extractErrorReason(error, fallback));
  }

  if (!isWrappedResponse<T>(response.data)) {
    throw new Error(extractBackendMessage(response.data) ?? fallback);
  }

  return response.data;
}

/**
 * Performs a DELETE request and rethrows request failures with normalized, readable messages.
 * @param url Request URL.
 * @param fallback Default message used when no server message is available.
 * @param config Optional axios request configuration.
 * @returns Resolves when the delete operation completes.
 */
export async function requestDelete(
  url: string,
  fallback: string,
  config?: AxiosRequestConfig,
): Promise<void> {
  try {
    await axiosLib.delete(url, config);
  }
  catch (error) {
    throw new Error(extractErrorReason(error, fallback));
  }
}

import type { Component } from 'vue';
import {
  createRouter,
  createWebHistory,
  type RouteRecordRaw,
} from 'vue-router';
import { useProfileStore } from '@/Auth/store/user-auth-store';
import loadingComponentRaw from '@/global-components/reusable/loading-component.vue';
import unauthorizedRaw from '@/global-components/reusable/unauthorized-component.vue';
import isa95EquipmentModelViewRaw from '@/modules/isa95-equipment-model/views/isa95-equipment-model-view.vue';
import isa95PhysicalAssetModelViewRaw from '@/modules/isa95-physical-asset-model/views/isa95-physical-asset-model-view.vue';
import { appLogger } from '@/utils/logger/app-logger.ts';

const isa95EquipmentModelView = isa95EquipmentModelViewRaw as Component;
const isa95PhysicalAssetModelView = isa95PhysicalAssetModelViewRaw as Component;
const loadingComponent = loadingComponentRaw as Component;
const unauthorized = unauthorizedRaw as Component;

const appRedirectUri = import.meta.env.APP_REDIRECT_URI as string | undefined;
let appBasePath: string | undefined;
if (appRedirectUri !== undefined && appRedirectUri !== '') {
  const parts: Array<string> = appRedirectUri.split('/');
  appBasePath = parts.pop();
}

const routes: Array<RouteRecordRaw> = [
  {
    component: isa95EquipmentModelView,
    meta: { requiresAuth: true, title: 'Equipment Configuration' },
    name: 'Isa95EquipmentModel',
    path: '/hry-set-ui/equipment',
    props: true,
  },
  {
    component: isa95PhysicalAssetModelView,
    meta: { requiresAuth: true, title: 'Physical Asset Model' },
    name: 'Isa95PhysicalAssetsModel',
    path: '/hry-set-ui/physical-assets',
    props: true,
  },
  {
    component: unauthorized,
    name: 'Unauthorized',
    path: '/unauthorized',
  },

  {
    component: loadingComponent,
    name: 'LoadingComponent',
    path: `/${appBasePath}/loading`,
  },
];

const router = createRouter({
  history: createWebHistory(),
  routes,
});

router.beforeEach(async (to, _from, next) => {
  if (to.meta.title) {
    document.title = `MESX.0 - ${to.meta.title as string}`;
  }

  const userAuth = useProfileStore();

  if (to.meta.requiresAuth) {
    try {
      await userAuth.authenticateUser();
      const user = await userAuth.getUser();
      if (user) {
        await userAuth.fetchUserAttributes();
        await userAuth.authorizeUser();
      }
      else {
        console.error('User not found');
        return next(`/${appBasePath}/unauthorized`);
      }
      return next();
    }
    catch (error) {
      appLogger.error(`Error during authentication or authorization: ${error}`);
      return next(`/${appBasePath}/unauthorized`);
    }
  }

  return next();
});

export { router };

import { ref, reactive } from 'vue';

/**
 * @returns The stored VALUEQ string from localStorage, or 'true' if not set.
 */
function getValueQ(): string {
  return globalThis.localStorage.getItem('VALUEQ') ?? 'true';
}

/**
 * @returns The stored VALUEE string from localStorage, or 'true' if not set.
 */
function getValueE(): string {
  return globalThis.localStorage.getItem('VALUEE') ?? 'true';
}

const state = reactive({
  valueE: ref(JSON.parse(getValueE()) as boolean),
  valueQ: ref(JSON.parse(getValueQ()) as boolean),
});

/**
 * Sets the value of valueQ in the state and updates localStorage.
 * @param value - The new value to be set for valueQ.
 */
function setValueQ(value: boolean): void {
  state.valueQ = value;
  globalThis.localStorage.setItem('VALUEQ', JSON.stringify(value));
}

/**
 * Sets the value of valueE in the state and updates localStorage.
 * @param value - The new value to be set for valueE.
 */
function setValueE(value: boolean): void {
  state.valueE = value;
  globalThis.localStorage.setItem('VALUEE', JSON.stringify(value));
}

// Export necessary functions and data
export { state, setValueQ, setValueE, getValueQ, getValueE };

