import { ref, type Ref } from 'vue';

/**
 * Generic composable that manages a confirmation dialog state.
 * It stores a payload of type `T`, controls dialog visibility,
 * and provides methods to open, cancel, and confirm the dialog.
 * @template T - Type of the payload handled by the confirmation dialog
 * @returns Object containing dialog state, payload, and open/cancel/confirm handlers
 */
export function useConfirmDialog<T>(): {
  cancel: () => void
  confirm: () => T | null
  isOpen: Ref<boolean>
  open: (payload: T) => void
  payload: Ref<T | null>
} {
  const isOpen = ref(false);
  const payload = ref<T | null>(null) as Ref<T | null>;

  /**
   * Opens the confirmation dialog with a given payload.
   * @param value - Data to associate with the confirmation action
   */
  function open(value: T): void {
    payload.value = value;
    isOpen.value = true;
  }

  /**
   * Cancels the confirmation dialog and clears the payload.
   */
  function cancel(): void {
    payload.value = null;
    isOpen.value = false;
  }

  /**
   * Confirms the action and returns the stored payload.
   * Also resets the dialog state.
   * @returns The confirmed payload or null if none exists
   */
  function confirm(): T | null {
    const value = payload.value;
    payload.value = null;
    isOpen.value = false;
    return value;
  }

  return {
    cancel,
    confirm,
    isOpen,
    open,
    payload,
  };
}

import { computed, ref, type ComputedRef } from 'vue';

/**
 * Simple composable that manages a boolean panel state (open/close/toggle).
 *
 * Useful for dialogs, side panels, drawers, and modals.
 * @param initial - Initial open state of the panel (default: false)
 * @returns Object containing reactive panel state and control methods
 */
export function usePanel(initial = false): {
  close: () => void
  isOpen: ComputedRef<boolean>
  open: () => void
  setOpen: (value: boolean) => void
  toggle: () => void
} {
  const openReference = ref(initial);

  /**
   * Opens the panel.
   */
  function open(): void {
    openReference.value = true;
  }

  /**
   * Closes the panel.
   */
  function close(): void {
    openReference.value = false;
  }

  /**
   * Toggles the panel state between open and closed.
   */
  function toggle(): void {
    openReference.value = !openReference.value;
  }

  /**
   * Sets the panel state explicitly.
   * @param value - True to open the panel, false to close it
   */
  function setOpen(value: boolean): void {
    openReference.value = value;
  }

  const isOpen = computed(() => openReference.value);

  return {
    close,
    isOpen,
    open,
    setOpen,
    toggle,
  };
}

import {
  computed,
  ref,
  watch,
  type ComputedRef,
  type Ref,
} from 'vue';

import type { Isa95PropertyDataTypeDto } from '../services/api';
import type { PropertyFormState } from '../types';
import {
  fromQuasarDateTimeValue,
  normalizeUniqueValues,
  parseAllowedValues,
  resolvePropertyDataTypeKind,
  toDateTimeValue,
  toDelimitedString,
  toQuasarDateTimeValue,
} from '../utils/property-value';

/**
 * Composable for managing property form state and semantics in equipment class properties.
 * @param options - Configuration object for the composable
 * @param options.dataTypes - Reference to available property data types
 * @param options.initialValue - Reference to the initial property form state
 * @param options.modelValue - Reference to dialog visibility state
 * @param options.onInvalidListValues - Optional callback when list validation fails
 * @returns Object containing form state, computed values, and handler functions
 */
export function usePropertyFormSemantics(options: {
  dataTypes: Ref<Array<Isa95PropertyDataTypeDto>>
  initialValue: Ref<PropertyFormState>
  modelValue: Ref<boolean>
  onInvalidListValues?: (message: string) => void
}): {
  addListValue: () => void
  booleanDefault: ComputedRef<boolean>
  handleClassPropertyTypeChange: () => void
  handleDataTypeChange: () => void
  handleListInputKeydown: (event: KeyboardEvent) => void
  isListArrayCardinality: ComputedRef<boolean>
  listAllowedValueItems: ComputedRef<Array<string>>
  listDefaultValueModel: ComputedRef<string | Array<string> | undefined>
  listInputValue: Ref<string>
  listValuePlaceholder: ComputedRef<string>
  localForm: Ref<PropertyFormState>
  propertyNameInput: ComputedRef<string>
  quasarDateTimeValue: ComputedRef<string>
  removeListValue: (index: number) => void
  selectedClassPropertyType: ComputedRef<string>
  selectedDataTypeKind: ComputedRef<'boolean' | 'date' | 'list' | 'number' | 'string' | undefined>
  showValueEditor: ComputedRef<boolean>
  syncFromInitial: () => void
  toSubmitPayload: () => PropertyFormState | undefined
  updateDateTimeValue: (value: string | null) => void
  valueFieldLabel: ComputedRef<string>
  valueFieldPlaceholder: ComputedRef<string>
} {
  const localForm = ref<PropertyFormState>({
    allowedValues: undefined,
    cardinality: 'single',
    classPropertyType: 'InstanceType',
    code: '',
    defaultValue: undefined,
    description: undefined,
    equipmentClassId: undefined,
    length: undefined,
    propertyDataTypeId: undefined,
    scale: undefined,
  });

  const listInputValue = ref('');

  const propertyNameInput = computed({
    get: () => {
      const code = localForm.value.code;
      return code === undefined || code.trim().length === 0
        ? ''
        : code;
    },
    set: (value: string) => {
      localForm.value.code = value;
    },
  });

  const selectedDataTypeCode = computed(() => {
    if (localForm.value.propertyDataTypeId === undefined) return;
    const propertyDataTypeId = Number(localForm.value.propertyDataTypeId);
    return options.dataTypes.value.find(dt => dt.id === propertyDataTypeId)?.code;
  });

  const selectedDataTypeKind = computed(() => resolvePropertyDataTypeKind(
    selectedDataTypeCode.value,
    localForm.value.propertyDataTypeId,
  ));

  const selectedClassPropertyType = computed(
    () => localForm.value.classPropertyType ?? 'InstanceType',
  );

  const showValueEditor = computed(
    () => selectedDataTypeKind.value !== undefined && selectedClassPropertyType.value !== 'InstanceType',
  );

  const valueFieldLabel = computed(() =>
    selectedClassPropertyType.value === 'ClassType' ? 'Class Value' : 'Default Value',
  );

  const valueFieldPlaceholder = computed(() => {
    if (selectedDataTypeKind.value === undefined) {
      return 'Select a data type first';
    }

    return selectedClassPropertyType.value === 'ClassType'
      ? 'Enter a class value'
      : 'Enter a default value';
  });

  const listAllowedValueItems = computed({
    get: () => parseAllowedValues(localForm.value.allowedValues),
    set: (values: Array<string>) => {
      localForm.value.allowedValues = toDelimitedString(values);
    },
  });

  const isListArrayCardinality = computed(
    () => selectedDataTypeKind.value === 'list' && localForm.value.cardinality === 'array',
  );

  const listValuePlaceholder = computed(() => {
    if (listAllowedValueItems.value.length === 0) {
      return 'Add list values first';
    }

    if (isListArrayCardinality.value) {
      return selectedClassPropertyType.value === 'ClassType'
        ? 'Select one or more class values'
        : 'Select one or more default values';
    }

    return selectedClassPropertyType.value === 'ClassType'
      ? 'Select a class value'
      : 'Select a default value';
  });

  const listDefaultValueModel = computed<string | Array<string> | undefined>({
    get: () => {
      const values = parseAllowedValues(localForm.value.defaultValue);

      return isListArrayCardinality.value
        ? values
        : values[0];
    },
    set: (value) => {
      if (Array.isArray(value)) {
        localForm.value.defaultValue = toDelimitedString(value);
        return;
      }

      localForm.value.defaultValue = value !== undefined && value.length > 0
        ? value
        : undefined;
    },
  });

  /**
   *
   */
  function addListValue(): void {
    if (listInputValue.value.trim().length === 0) {
      return;
    }

    const updated = normalizeUniqueValues([
      ...parseAllowedValues(localForm.value.allowedValues),
      ...parseAllowedValues(listInputValue.value),
    ]);

    localForm.value.allowedValues = toDelimitedString(updated);
    listInputValue.value = '';
  }

  /**
   * Removes a list value at the specified index.
   * @param index - The index of the value to remove
   */
  function removeListValue(index: number): void {
    const currentValues = parseAllowedValues(localForm.value.allowedValues);
    const updated = currentValues.filter((_, itemIndex) => itemIndex !== index);
    localForm.value.allowedValues = toDelimitedString(updated);
  }

  /**
   * Handles keydown events for list value input field.
   * @param event - The keyboard event
   */
  function handleListInputKeydown(event: KeyboardEvent): void {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addListValue();
    }
  }

  const dateTimeValue = computed({
    get: () => toDateTimeValue(localForm.value.defaultValue),
    set: (value: string) => {
      localForm.value.defaultValue = value.length > 0 ? value : undefined;
    },
  });

  const quasarDateTimeValue = computed(() => toQuasarDateTimeValue(localForm.value.defaultValue));

  /**
   * Updates the datetime value from Quasar format.
   * @param value - The Quasar datetime value or null
   */
  function updateDateTimeValue(value: string | null): void {
    dateTimeValue.value = value === null ? '' : fromQuasarDateTimeValue(value);
  }

  const booleanDefault = computed({
    get: () => {
      const value = localForm.value.defaultValue;
      return value === 'true' || value === 'TRUE';
    },
    set: (value: boolean) => {
      localForm.value.defaultValue = value ? 'true' : 'false';
    },
  });

  /**
   *
   */
  function normalizeListDefaultValue(): void {
    if (selectedDataTypeKind.value !== 'list') {
      return;
    }

    if (selectedClassPropertyType.value === 'InstanceType') {
      localForm.value.defaultValue = undefined;
      return;
    }

    const availableValues = listAllowedValueItems.value;
    if (availableValues.length === 0) {
      localForm.value.defaultValue = undefined;
      return;
    }

    const selectedValues = parseAllowedValues(localForm.value.defaultValue)
      .filter(value => availableValues.includes(value));

    if (isListArrayCardinality.value) {
      localForm.value.defaultValue = selectedValues.length > 0
        ? toDelimitedString(selectedValues)
        : availableValues[0];
      return;
    }

    localForm.value.defaultValue = selectedValues[0] ?? availableValues[0];
  }

  /**
   *
   */
  function resetValueForSelection(): void {
    if (selectedClassPropertyType.value === 'InstanceType') {
      localForm.value.defaultValue = undefined;
      return;
    }

    switch (selectedDataTypeKind.value) {
      case 'boolean': {
        localForm.value.defaultValue = 'false';
        break;
      }
      case 'date':
      case 'number':
      case 'string': {
        localForm.value.defaultValue = undefined;
        break;
      }
      case 'list': {
        localForm.value.defaultValue = listAllowedValueItems.value[0];
        normalizeListDefaultValue();
        break;
      }
      default: {
        localForm.value.defaultValue = undefined;
        break;
      }
    }
  }

  /**
   *
   */
  function handleDataTypeChange(): void {
    if (selectedDataTypeKind.value !== 'list') {
      localForm.value.allowedValues = undefined;
    }

    resetValueForSelection();
  }

  /**
   *
   */
  function handleClassPropertyTypeChange(): void {
    resetValueForSelection();
  }

  /**
   *
   */
  function syncFromInitial(): void {
    localForm.value = { ...options.initialValue.value };
    listInputValue.value = '';
  }

  watch(listAllowedValueItems, (values) => {
    if (selectedDataTypeKind.value !== 'list') {
      return;
    }

    if (values.length === 0) {
      localForm.value.defaultValue = undefined;
      return;
    }

    normalizeListDefaultValue();
  });

  watch(isListArrayCardinality, () => {
    normalizeListDefaultValue();
  });

  watch(selectedClassPropertyType, (type) => {
    if (type === 'InstanceType') {
      localForm.value.defaultValue = undefined;
    }
  });

  watch(
    options.modelValue,
    (open) => {
      if (open) {
        syncFromInitial();
      }
    },
    { immediate: true },
  );

  watch(
    options.initialValue,
    () => {
      if (options.modelValue.value) {
        syncFromInitial();
      }
    },
    { deep: true },
  );

  /**
   * Converts the current form state to a submit payload.
   * @returns The serialized property form state, or undefined if validation fails
   */
  function toSubmitPayload(): PropertyFormState | undefined {
    const allowedValuesArray = selectedDataTypeKind.value === 'list'
      ? normalizeUniqueValues(listAllowedValueItems.value)
      : [];

    if (selectedDataTypeKind.value === 'list' && allowedValuesArray.length === 0) {
      options.onInvalidListValues?.(
        'List properties must have at least one value. Type values in the "List Values" field and press Enter or comma after each.',
      );
      return undefined;
    }

    return {
      ...localForm.value,
      allowedValues: toDelimitedString(allowedValuesArray),
    };
  }

  return {
    addListValue,
    booleanDefault,
    handleClassPropertyTypeChange,
    handleDataTypeChange,
    handleListInputKeydown,
    isListArrayCardinality,
    listAllowedValueItems,
    listDefaultValueModel,
    listInputValue,
    listValuePlaceholder,
    localForm,
    propertyNameInput,
    quasarDateTimeValue,
    removeListValue,
    selectedClassPropertyType,
    selectedDataTypeKind,
    showValueEditor,
    syncFromInitial,
    toSubmitPayload,
    updateDateTimeValue,
    valueFieldLabel,
    valueFieldPlaceholder,
  };
}

