/**
 * Extracts authorization headers with bearer token if available.
 * @returns Record containing authorization header, or empty object if no token
 */
function authHeaders(): Record<string, string> {
  return buildBearerAuthHeaders(token);
}

/**
 * Fetch the restricted ISA-95 hierarchy descriptions for a given plant code.
 * @param plant - Plant code to filter hierarchy by (e.g. "S001")
 * @returns Array of hierarchy description root nodes
 */
export async function getRestrictedHierarchyDescriptions(
  plant: string,
): Promise<Array<Isa95HierarchyDescriptionNodeDto>> {
  const body = await requestGet<Array<Isa95HierarchyDescriptionNodeDto> | null>(
    `${apiBase}/hierarchy`,
    'Failed to load ISA95 hierarchy descriptions.',
    { headers: authHeaders(), params: { plant } },
  );

  return unwrapArrayPayload(body);
}

