  const body = await requestGet<Array<Isa95EquipmentLevelDto> | null>(
    `${apiBase}/equipment-levels`,
    'Failed to load equipment levels.',
    { headers: authHeaders() },
  );

  return unwrapArrayPayload(body);
}

