import { defineStore } from 'pinia';
import { computed, inject, ref, type ComputedRef, type Ref } from 'vue';

import { formatDisplayValue } from '../../../utils/helpers/format-display';
import {
  createEquipmentClass as createEquipmentClassApi,
  createEquipmentClassProperty as createEquipmentClassPropertyApi,
  deleteEquipmentClassProperty as deleteEquipmentClassPropertyApi,
  deleteEquipmentClass as deleteEquipmentClassApi,
  getEquipmentClassPropertiesByClass as getEquipmentClassPropertiesByClassApi,
  getEquipmentClassWithRelations as getEquipmentClassWithRelationsApi,
  getEquipmentClasses as getEquipmentClassesApi,
  getEquipmentLevels as getEquipmentLevelsApi,
  getPropertyDataTypes as getPropertyDataTypesApi,
  updateEquipmentClassProperty as updateEquipmentClassPropertyApi,
  updateEquipmentClass as updateEquipmentClassApi,
  Isa95EquipmentClassDto,
  Isa95EquipmentClassPropertyDto,
  Isa95EquipmentDto,
  Isa95EquipmentEquipmentClassDto,
  Isa95EquipmentLevelDto,
  Isa95PropertyDataTypeDto,
} from '../services/api';

import type {
  EquipmentClassFormState,
  EquipmentClassTableRow,
  InlineEditState,
  PropertyFormState,
} from '../types';
import { getSqlIdentifierValidationMessage } from '../utils/sql-identifier-validation';
import { getErrorMessage, normalizeClassProperty, type NotifyService } from '../utils/store-helpers';

export interface EquipmentClassStoreState {
  classRows: Ref<Array<Isa95EquipmentClassDto>>
  classTableRows: ComputedRef<Array<EquipmentClassTableRow>>
  createdCode: Ref<string>
  createdDialogOpen: Ref<boolean>
  createdId: Ref<number | undefined>
  deleteDialogOpen: Ref<boolean>
  dialogOpen: Ref<boolean>
  editingId: Ref<number | undefined>
  form: Ref<EquipmentClassFormState>
  inlineEditForm: Ref<{
    code: string
    description: string | undefined
    equipmentLevelId: number | undefined
  }>
  inlineEditingRowId: Ref<number | undefined>
  isEditing: Ref<boolean>
  levelOptions: ComputedRef<Array<{ label: string, value: number }>>
  propertyDataTypes: Ref<Array<Isa95PropertyDataTypeDto>>
}

/**
 * Converts a property name into an uppercase comparison key.
 * @param value Raw property name or displayed code.
 * @returns Uppercase key used for duplicate checks.
 */
function getComparablePropertyCode(value: string | undefined): string {
  const trimmed = value?.trim();
  return trimmed?.toUpperCase() ?? '';
}

export const useEquipmentClassStore = defineStore('isa95EquipmentClass', () => {
  const notify = inject<NotifyService>('notify');

  const classRows = ref<Array<Isa95EquipmentClassDto>>([]);
  const equipmentLevels = ref<Array<Isa95EquipmentLevelDto>>([]);
  const selectedClassRows = ref<Array<EquipmentClassTableRow>>([]);
  const inlineEditingRowId = ref<number | undefined>(undefined);
  const inlineEditForm = ref({
    code: '',
    description: undefined as string | undefined,
    equipmentLevelId: undefined as number | undefined,
  });
  const deleteDialogOpen = ref(false);
  const pendingDeleteClassId = ref<number | undefined>(undefined);
  const pendingDeleteClassCode = ref('');

  const dialogOpen = ref(false);
  const isEditing = ref(false);
  const editingId = ref<number | undefined>(undefined);

  const createdDialogOpen = ref(false);
  const createdCode = ref('');
  const createdId = ref<number | undefined>(undefined);

  const form = ref<EquipmentClassFormState>({
    code: '',
    description: '',
    equipmentLevelId: undefined,
  });
  const submitting = ref(false);

  const classProperties = ref<Array<Isa95EquipmentClassPropertyDto>>([]);
  const propertyDataTypes = ref<Array<Isa95PropertyDataTypeDto>>([]);
  const propertiesViewOpen = ref(false);
  const selectedClass = ref<Isa95EquipmentClassDto | undefined>(undefined);
  const searchQuery = ref('');
  const plantFilter = ref('all');
  const propertyPanelOpen = ref(false);
  const propertyIsEditing = ref(false);
  const propertyEditingId = ref<number | undefined>(undefined);
  const propertyEditAllowed = ref(true);
  const propertyForm = ref<PropertyFormState>({
    allowedValues: undefined,
    cardinality: 'single',
    classPropertyType: 'InstanceType',
    code: '',
    defaultValue: undefined,
    description: undefined,
    equipmentClassId: undefined,
    length: undefined,
    propertyDataTypeId: undefined,
    scale: undefined,
  });
  const relatedPanelOpen = ref(false);
  const propertyDeleteDialogOpen = ref(false);
  const pendingDeletePropertyId = ref<number | undefined>(undefined);
  const propertyInlineEditingRowId = ref<number | undefined>(undefined);
  const propertyInlineEditForm = ref<InlineEditState>({
    defaultValue: undefined,
    description: undefined,
    length: undefined,
    propertyDataTypeId: undefined,
  });

  const levelOptions = computed(() =>
    equipmentLevels.value.map(level => ({
      label: `${level.code} (#${level.id})`,
      value: level.id,
    })),
  );

  /**
   * Loads equipment levels once and reuses them for create/edit dialogs.
   */
  async function ensureEquipmentLevels(): Promise<void> {
    if (equipmentLevels.value.length > 0) {
      return;
    }

    equipmentLevels.value = await getEquipmentLevelsApi();
  }

  const classTableRows = computed<Array<EquipmentClassTableRow>>(() =>
    classRows.value.map(row => ({
      ...row,
      description: row.description ?? '',
      numberOfProperties: row.equipmentClassPropertiesCount ?? 0,
    })),
  );

  /**
   * Loads equipment classes into the store without fetching per-row relations.
   */
  async function load(): Promise<void> {
    try {
      const classes = await getEquipmentClassesApi();

      classRows.value = classes;
    }
    catch (error) {
      classRows.value = [];
      equipmentLevels.value = [];
      notify?.error({
        message: error instanceof Error ? error.message : 'Failed to load equipment classes.',
      });
    }
  }

  /**
   * Selects the equipment class row that matches the provided identifier.
   * @param id Equipment class identifier to select.
   */
  function selectById(id: number): void {
    const target = classTableRows.value.find(row => row.id === id);
    selectedClassRows.value = target ? [target] : [];
  }

  /**
   * Opens the create dialog with a reset equipment class form.
   */
  async function openCreate(): Promise<void> {
    await ensureEquipmentLevels();
    isEditing.value = false;
    editingId.value = undefined;
    inlineEditingRowId.value = undefined;
    form.value = {
      code: '',
      description: '',
      equipmentLevelId: levelOptions.value[0]?.value ?? 1,
    };
    dialogOpen.value = true;
  }

  /**
   * Opens the edit dialog and seeds the form with the selected equipment class values.
   * @param row Equipment class row to edit.
   */
  async function openEdit(row: EquipmentClassTableRow): Promise<void> {
    let details: Isa95EquipmentClassDto | undefined;

    try {
      await ensureEquipmentLevels();
      details = await getEquipmentClassWithRelationsApi(row.id);
    }
    catch (error) {
      notify?.warning({
        message: getErrorMessage(error, 'Unable to refresh class details. Using current row values.'),
      });
    }

    if (details) {
      classRows.value = classRows.value.map(existing =>
        existing.id === row.id
          ? {
              ...existing,
              ...details,
              description: details.description ?? existing.description,
            }
          : existing,
      );
    }

    isEditing.value = true;
    editingId.value = details?.id ?? row.id;
    inlineEditingRowId.value = undefined;
    form.value = {
      code: details?.code ?? row.code,
      description: details?.description ?? row.description ?? '',
      equipmentLevelId: details?.equipmentLevelId ?? row.equipmentLevelId ?? undefined,
    };
    dialogOpen.value = true;
  }

  /**
   * Creates a new equipment class or updates the currently edited one.
   * @returns A promise that resolves with the created record when a new class is created.
   */
  async function submit(): Promise<{ created: Isa95EquipmentClassDto | undefined }> {
    if (submitting.value) {
      return { created: undefined };
    }

    const code = form.value.code.trim();
    const description = form.value.description.trim();
    const levelId = form.value.equipmentLevelId;

    if (code.length === 0 || description.length === 0) {
      notify?.warning({ message: 'Class name and description are required.' });
      return { created: undefined };
    }

    // Validate code is a valid SQL identifier
    const codeValidationMessage = getSqlIdentifierValidationMessage(code, 'Class name');
    if (codeValidationMessage) {
      notify?.warning({ message: codeValidationMessage });
      return { created: undefined };
    }

    submitting.value = true;
    try {
      if (isEditing.value && editingId.value !== undefined) {
        const updated = await updateEquipmentClassApi(editingId.value, {
          code,
          description,
          descriptionLanguageCode: 'EN',
        });

        if (!updated) {
          notify?.error({ message: 'Failed to save equipment class.' });
          return { created: undefined };
        }

        classRows.value = classRows.value.map(row => (
          row.id === editingId.value
            ? {
                ...row,
                ...updated,
                description,
                equipmentLevelId: updated.equipmentLevelId ?? row.equipmentLevelId ?? null,
              }
            : row
        ));

        notify?.success({ message: 'Equipment class updated.' });
        dialogOpen.value = false;
        return { created: undefined };
      }

      const created = await createEquipmentClassApi({
        className: code,
        description,
        descriptionLanguageCode: 'EN',
      });

      if (!created) {
        notify?.error({ message: 'Failed to create equipment class.' });
        return { created: undefined };
      }

      const createdRow: Isa95EquipmentClassDto = {
        ...created,
        description,
        equipmentLevelId: created.equipmentLevelId ?? levelId ?? null,
      };

      classRows.value = [...classRows.value, createdRow];

      notify?.success({ message: 'Equipment class created.' });
      dialogOpen.value = false;
      createdCode.value = createdRow.code;
      createdId.value = createdRow.id;
      createdDialogOpen.value = true;
      return { created: createdRow };
    }
    catch (error) {
      notify?.error({
        message: error instanceof Error ? error.message : 'Failed to save equipment class.',
      });
      return { created: undefined };
    }
    finally {
      submitting.value = false;
    }
  }

  /**
   * Deletes an equipment class and removes its related local state.
   * @param id Equipment class identifier to delete.
   * @returns A promise that resolves to true when the class is removed successfully.
   */
  async function remove(id: number): Promise<boolean> {
    try {
      await deleteEquipmentClassApi(id);
      classRows.value = classRows.value.filter(row => row.id !== id);

      notify?.success({ message: 'Equipment class deleted.' });
      return true;
    }
    catch (error) {
      notify?.error({
        message: error instanceof Error ? error.message : 'Failed to delete equipment class.',
      });
      return false;
    }
  }

  /**
   * Starts inline editing for the provided equipment class row.
   * @param row Equipment class row to edit inline.
   */
  function startInlineEdit(row: EquipmentClassTableRow): void {
    inlineEditingRowId.value = row.id;
    inlineEditForm.value = {
      code: row.code,
      description: row.description,
      equipmentLevelId: row.equipmentLevelId ?? levelOptions.value[0]?.value ?? undefined,
    };
  }

  /**
   * Cancels the active inline edit session for an equipment class.
   */
  function cancelInlineEdit(): void {
    inlineEditingRowId.value = undefined;
  }

  /**
   * Persists inline edits for an equipment class row.
   * @param row Equipment class row being updated.
   * @returns A promise that resolves to true when the update succeeds.
   */
  async function saveInlineEdit(row: EquipmentClassTableRow): Promise<boolean> {
    const code = inlineEditForm.value.code.trim();
    const levelId = inlineEditForm.value.equipmentLevelId;
    const trimmedDescription = inlineEditForm.value.description?.trim();
    const description = trimmedDescription !== undefined && trimmedDescription.length > 0
      ? trimmedDescription
      : undefined;

    if (code.length === 0 || levelId === undefined) {
      notify?.warning({ message: 'Code and equipment level are required.' });
      return false;
    }

    // Validate code is a valid SQL identifier
    const codeValidationMessage = getSqlIdentifierValidationMessage(code, 'Code');
    if (codeValidationMessage) {
      notify?.warning({ message: codeValidationMessage });
      return false;
    }

    try {
      const updated = await updateEquipmentClassApi(row.id, {
        code,
        description,
        descriptionLanguageCode: 'EN',
      });

      if (!updated) {
        notify?.error({ message: 'Failed to update equipment class.' });
        return false;
      }

      classRows.value = classRows.value.map(r =>
        r.id === row.id
          ? {
              ...r,
              ...updated,
              description: inlineEditForm.value.description?.trim() ?? r.description,
              equipmentLevelId: updated.equipmentLevelId ?? Number(levelId),
            }
          : r,
      );
      notify?.success({ message: 'Equipment class updated.' });
      inlineEditingRowId.value = undefined;
      return true;
    }
    catch (error) {
      notify?.error({
        message: error instanceof Error ? error.message : 'Failed to update equipment class.',
      });
      return false;
    }
  }

  /**
   * Opens the delete confirmation dialog for an equipment class row.
   * @param row Equipment class row queued for deletion.
   */
  function requestDelete(row: EquipmentClassTableRow): void {
    pendingDeleteClassId.value = row.id;
    pendingDeleteClassCode.value = row.code;
    deleteDialogOpen.value = true;
  }

  /**
   * Closes the delete confirmation dialog and clears its pending state.
   */
  function cancelDelete(): void {
    deleteDialogOpen.value = false;
    pendingDeleteClassId.value = undefined;
    pendingDeleteClassCode.value = '';
  }

  /**
   * Confirms deletion of the pending equipment class.
   * @returns True when the deletion succeeds, false when nothing was pending.
   */
  async function confirmDelete(): Promise<boolean> {
    const id = pendingDeleteClassId.value;
    if (id === undefined) {
      cancelDelete();
      return false;
    }

    deleteDialogOpen.value = false;
    pendingDeleteClassId.value = undefined;
    pendingDeleteClassCode.value = '';
    return await remove(id);
  }

  /**
   * Closes the post-creation confirmation dialog.
   */
  function closeCreatedDialog(): void {
    createdDialogOpen.value = false;
  }

  /**
   * Loads local property data-type options used by the properties table and panel.
   */
  async function loadProperties(): Promise<void> {
    propertyDataTypes.value = await getPropertyDataTypesApi();
  }

  /**
   * Refreshes the property rows for a specific equipment class from the backend.
   * @param classId Equipment class identifier.
   */
  async function loadPropertiesByClass(classId: number): Promise<void> {
    const classPropertiesResponse = await getEquipmentClassPropertiesByClassApi(classId);
    const properties = classPropertiesResponse.map(property => normalizeClassProperty(property));
    classProperties.value = [
      ...classProperties.value.filter(property => property.equipmentClassId !== classId),
      ...properties,
    ];
  }

  /**
   * Opens the class properties view for the selected equipment class.
   * @param equipmentClass Equipment class whose properties should be displayed.
   */
  async function openPropertiesView(equipmentClass: Isa95EquipmentClassDto): Promise<void> {
    try {
      selectedClass.value = await getEquipmentClassWithRelationsApi(equipmentClass.id) ?? equipmentClass;
    }
    catch (error) {
      selectedClass.value = equipmentClass;
      notify?.warning({
        message: getErrorMessage(error, 'Unable to refresh class details. Showing current data.'),
      });
    }

    try {
      await loadPropertiesByClass(equipmentClass.id);
    }
    catch (error) {
      classProperties.value = classProperties.value.filter(property => property.equipmentClassId !== equipmentClass.id);
      notify?.warning({
        message: error instanceof Error
          ? error.message
          : 'Unable to load class properties.',
      });
    }

    searchQuery.value = '';
    plantFilter.value = 'all';
    propertyInlineEditingRowId.value = undefined;
    propertiesViewOpen.value = true;
  }

  /**
   * Closes the class properties view and clears related filters.
   */
  function closePropertiesView(): void {
    propertiesViewOpen.value = false;
    relatedPanelOpen.value = false;
    searchQuery.value = '';
    plantFilter.value = 'all';
  }

  /**
   * Resets the Equipment Classes tab back to its initial list view.
   */
  function resetTabState(): void {
    closePropertiesView();
    selectedClass.value = undefined;
    propertyPanelOpen.value = false;
    propertyDeleteDialogOpen.value = false;
    propertyInlineEditingRowId.value = undefined;
    propertyIsEditing.value = false;
    propertyEditingId.value = undefined;
  }

  /**
   * Opens the property creation panel with a reset property form.
   */
  function openCreateProperty(): void {
    propertyIsEditing.value = false;
    propertyEditingId.value = undefined;
    propertyEditAllowed.value = true;
    propertyForm.value = {
      allowedValues: undefined,
      cardinality: 'single',
      classPropertyType: 'InstanceType',
      code: '',
      defaultValue: undefined,
      description: undefined,
      equipmentClassId: selectedClass.value?.id,
      length: undefined,
      propertyDataTypeId: undefined,
      scale: undefined,
    };
    propertyPanelOpen.value = true;
  }

  /**
   * Opens the property panel in edit mode, seeding the form from the selected property row.
   * @param row Equipment class property row to edit.
   */
  function openEditProperty(row: Isa95EquipmentClassPropertyDto): void {
    if (!row.isCustom) {
      propertyEditAllowed.value = false;
      notify?.warning({ message: 'Only custom properties can be edited.' });
      return;
    }

    propertyIsEditing.value = true;
    propertyEditingId.value = row.id;
    propertyEditAllowed.value = true;

    // Convert allowedValues array from backend response to comma-delimited string for form
    const allowedValuesString = Array.isArray(row.allowedValues) && row.allowedValues.length > 0
      ? row.allowedValues.join(',')
      : undefined;

    propertyForm.value = {
      allowedValues: allowedValuesString,
      cardinality: row.cardinality === 'array' ? 'array' : 'single',
      classPropertyType: row.classPropertyType ?? 'InstanceType',
      code: row.code,
      defaultValue: row.defaultValue ?? undefined,
      description: row.description ?? undefined,
      equipmentClassId: row.equipmentClassId,
      length: row.length ?? undefined,
      propertyDataTypeId: row.propertyDataTypeId,
      scale: row.scale ?? undefined,
    };
    propertyPanelOpen.value = true;
  }

  /**
   * Normalizes an optional property description by trimming whitespace.
   * @param description Raw description from the property form.
   * @returns The trimmed description, or undefined when empty.
   */
  function getNormalizedPropertyDescription(
    description: string | undefined,
  ): string | undefined {
    const trimmedDescription = description?.trim();

    return trimmedDescription !== undefined && trimmedDescription.length > 0
      ? trimmedDescription
      : undefined;
  }

  /**
   * Resolves the class property type to a trimmed value or the default type.
   * @param classPropertyType Raw class property type from the form.
   * @returns A valid class property type string.
   */
  function getNormalizedClassPropertyType(
    classPropertyType: string | undefined,
  ): string {
    const trimmedClassPropertyType = classPropertyType?.trim();
    const normalizedClassPropertyType = trimmedClassPropertyType !== undefined
      && trimmedClassPropertyType.length > 0
      ? trimmedClassPropertyType
      : 'InstanceType';

    return normalizedClassPropertyType === 'DefaultValueType'
      ? 'DefaultType'
      : normalizedClassPropertyType;
  }

  /**
   * Builds a compatibility semantics payload so both the old and new backend
   * contracts can persist property metadata during rollout.
   * @param cardinality - The property cardinality ('single' or 'array')
   * @param classPropertyType - The class property type
   * @param defaultValue - The default property value
   * @param allowedValues - Array of allowed values for list properties
   * @param length - Optional maximum length metadata for compatible backends.
   * @returns Semantics payload object with camelCase property names
   */
  function buildPropertySemantics(
    cardinality: 'single' | 'array',
    classPropertyType: string,
    defaultValue: string | number | undefined,
    allowedValues: Array<string> | undefined,
    length: number | undefined,
  ): Record<string, unknown> {
    const serializedDefaultValue = defaultValue === undefined
      ? undefined
      : String(defaultValue);

    // Only camelCase keys for lint compliance
    return {
      ...(allowedValues === undefined
        ? {}
        : {
            allowedValues,
          }),
      cardinality,
      classPropertyType,
      ...(length === undefined
        ? {}
        : { length }),
      ...(defaultValue === undefined
        ? {}
        : { defaultValue: serializedDefaultValue }),
    };
  }

  /**
   * Returns currently loaded properties for the active class.
   * @returns Combined loaded property rows for the selected/edited class.
   */
  function getCurrentClassProperties(): Array<Isa95EquipmentClassPropertyDto> {
    const classId = Number(
      propertyForm.value.equipmentClassId
      ?? selectedClass.value?.id
      ?? 0,
    );

    if (classId <= 0) {
      return [];
    }

    const loadedProperties = classProperties.value.filter(property => property.equipmentClassId === classId);
    const relationProperties = (selectedClass.value?.equipmentClassProperties ?? []).filter(
      property => property.equipmentClassId === classId,
    );

    return [...loadedProperties, ...relationProperties].filter(
      (property, index, properties) => properties.findIndex(candidate => candidate.id === property.id) === index,
    );
  }

  /**
   * Checks whether the current property name would duplicate an existing class property.
   * @returns True when another property already uses the same displayed name.
   */
  function hasDuplicatePropertyCode(): boolean {
    const currentCode = getComparablePropertyCode(propertyForm.value.code);

    if (currentCode.length === 0) {
      return false;
    }

    return getCurrentClassProperties().some((property) => {
      const isDifferentProperty = propertyEditingId.value === undefined
        ? true
        : property.id !== propertyEditingId.value;

      return isDifferentProperty
        && getComparablePropertyCode(formatDisplayValue(property.code)) === currentCode;
    });
  }

  /**
   * Builds the normalized create/update payload for a class property.
   * @returns API-ready payload derived from the current property form state.
   */
  function buildPropertyPayload() {
    const code = propertyForm.value.code.trim();
    const cardinality = propertyForm.value.cardinality ?? 'single';
    const classPropertyType = getNormalizedClassPropertyType(
      propertyForm.value.classPropertyType,
    );
    const rawAllowedValues = propertyForm.value.allowedValues;

    // Parse allowedValues from comma-separated string to array for semantics
    const allowedValuesArray = rawAllowedValues !== undefined && rawAllowedValues.length > 0
      ? Array.from(new Set(
          rawAllowedValues
            .split(',')
            .map(value => value.trim())
            .filter(value => value.length > 0),
        ))
      : undefined;

    return {
      code,
      description: getNormalizedPropertyDescription(
        propertyForm.value.description,
      ),
      equipmentClassId: Number(propertyForm.value.equipmentClassId ?? 0),
      length:
        propertyForm.value.length === undefined
          ? undefined
          : Number(propertyForm.value.length),
      propertyDataTypeId: Number(propertyForm.value.propertyDataTypeId ?? 1),
      propertySemanticsJson: buildPropertySemantics(
        cardinality,
        classPropertyType,
        propertyForm.value.defaultValue,
        allowedValuesArray,
        propertyForm.value.length === undefined
          ? undefined
          : Number(propertyForm.value.length),
      ),
      scale:
        propertyForm.value.scale === undefined
          ? undefined
          : Number(propertyForm.value.scale),
    };
  }

  /**
   * Reloads properties for the currently selected class when one is active.
   * @returns A promise that resolves after the class property list is refreshed.
   */
  async function refreshSelectedClassProperties(): Promise<void> {
    if (selectedClass.value?.id !== undefined) {
      await loadPropertiesByClass(selectedClass.value.id);
    }
  }

  /**
   * Updates the currently edited class property through the API.
   * @param editId Identifier of the property being updated.
   * @returns A promise that resolves to true when the update succeeds.
   */
  async function updateProperty(editId: number): Promise<boolean> {
    const payload = buildPropertyPayload();
    const updated = await updateEquipmentClassPropertyApi(editId, {
      code: payload.code,
      ...(payload.description === undefined
        ? {}
        : {
            description: payload.description,
            descriptionCode: 'EN',
          }),
      equipmentClassId: payload.equipmentClassId,
      length: payload.length,
      propertyDataTypeId: payload.propertyDataTypeId,
      propertySemanticsJson: payload.propertySemanticsJson,
      scale: payload.scale,
    });

    if (updated === undefined) {
      notify?.error({ message: 'Failed to update property.' });
      return false;
    }

    await refreshSelectedClassProperties();
    notify?.success({ message: 'Property updated.' });
    return true;
  }

  /**
   * Creates a new class property through the API.
   * @returns A promise that resolves to true when the creation succeeds.
   */
  async function createProperty(): Promise<boolean> {
    const payload = buildPropertyPayload();
    const apiPayload = {
      code: payload.code,
      ...(payload.description === undefined
        ? {}
        : {
            description: payload.description,
            descriptionCode: 'EN',
          }),
      equipmentClassId: payload.equipmentClassId,
      length: payload.length,
      propertyDataTypeId: payload.propertyDataTypeId,
      propertySemanticsJson: payload.propertySemanticsJson,
      scale: payload.scale,
    };

    const created = await createEquipmentClassPropertyApi(apiPayload);

    if (created === undefined) {
      notify?.error({ message: 'Failed to create property.' });
      return false;
    }

    await refreshSelectedClassProperties();
    notify?.success({ message: 'Property created.' });
    return true;
  }

  /**
   * Creates a new class property or updates the currently edited property.
   * @param payload - Optional property form state to merge before submit.
   * @returns A promise that resolves to true when the property is saved successfully.
   */
  async function submitProperty(payload?: PropertyFormState): Promise<boolean> {
    if (payload !== undefined) {
      propertyForm.value = {
        ...propertyForm.value,
        ...payload,
      };
    }

    if (propertyIsEditing.value && !propertyEditAllowed.value) {
      notify?.warning({ message: 'Only custom properties can be updated.' });
      return false;
    }

    const hasRequired
      = propertyForm.value.code.trim().length > 0
        && propertyForm.value.propertyDataTypeId !== undefined;

    if (!hasRequired) {
      notify?.warning({ message: 'Code and data type are required.' });
      return false;
    }

    // Validate code is a valid SQL identifier
    const code = propertyForm.value.code.trim();
    const codeValidationMessage = getSqlIdentifierValidationMessage(code, 'Property code');
    if (codeValidationMessage) {
      notify?.warning({ message: codeValidationMessage });
      return false;
    }

    if (hasDuplicatePropertyCode()) {
      notify?.error({ message: 'Property name already exists.' });
      return false;
    }

    try {
      const saved = propertyIsEditing.value && propertyEditingId.value !== undefined
        ? await updateProperty(propertyEditingId.value)
        : await createProperty();

      if (!saved) {
        return false;
      }

      propertyPanelOpen.value = false;
      return true;
    }
    catch (error) {
      notify?.error({ message: getErrorMessage(error, 'Failed to save property.') });
      return false;
    }
  }

  /**
   * Deletes an equipment class property and refreshes the property list.
   * @param id Equipment class property identifier to delete.
   * @returns A promise that resolves to true when the deletion succeeds.
   */
  async function removeProperty(id: number): Promise<boolean> {
    propertyInlineEditingRowId.value = undefined;
    try {
      await deleteEquipmentClassPropertyApi(id);
      classProperties.value = classProperties.value.filter(p => p.id !== id);
      if (selectedClass.value?.id !== undefined) {
        classRows.value = classRows.value.map(row =>
          row.id === selectedClass.value?.id
            ? {
                ...row,
                equipmentClassPropertiesCount: Math.max(
                  (row.equipmentClassPropertiesCount ?? 0) - 1,
                  0,
                ),
              }
            : row,
        );
      }
      notify?.success({ message: 'Property deleted.' });
      return true;
    }
    catch (error) {
      notify?.error({ message: 'Failed to delete property.' });
      console.error('Failed to delete property', error);
      return false;
    }
  }

  /**
   * Opens the delete confirmation dialog for an equipment class property.
   * @param row Equipment class property identifier queued for deletion.
   */
  function requestPropertyDelete(row: Isa95EquipmentClassPropertyDto): void {
    if (!row.isCustom) {
      notify?.warning({ message: 'Only custom properties can be deleted.' });
      return;
    }

    pendingDeletePropertyId.value = row.id;
    propertyDeleteDialogOpen.value = true;
  }

  /**
   * Closes the property delete confirmation dialog and clears its pending state.
   */
  function cancelPropertyDelete(): void {
    propertyDeleteDialogOpen.value = false;
    pendingDeletePropertyId.value = undefined;
  }

  /**
   * Confirms deletion of the pending equipment class property.
   * @returns True when the property is deleted, otherwise false.
   */
  async function confirmPropertyDelete(): Promise<boolean> {
    const id = pendingDeletePropertyId.value;
    if (id === undefined) {
      cancelPropertyDelete();
      return false;
    }

    propertyDeleteDialogOpen.value = false;
    pendingDeletePropertyId.value = undefined;
    return await removeProperty(id);
  }

  /**
   * Starts inline editing for the provided equipment class property row.
   * @param row Equipment class property row to edit inline.
   */
  function startPropertyInlineEdit(row: Isa95EquipmentClassPropertyDto): void {
    propertyInlineEditingRowId.value = row.id;
    propertyInlineEditForm.value = {
      defaultValue: row.defaultValue ?? undefined,
      description: row.description ?? undefined,
      length: row.length ?? undefined,
      propertyDataTypeId: row.propertyDataTypeId,
    };
  }

  /**
   * Cancels the active inline edit session for a class property.
   */
  function cancelPropertyInlineEdit(): void {
    propertyInlineEditingRowId.value = undefined;
  }

  /**
   * Persists inline edits for an equipment class property row.
   * @param row Equipment class property row being updated.
   */
  function savePropertyInlineEdit(row: Isa95EquipmentClassPropertyDto): void {
    try {
      classProperties.value = classProperties.value.map(p =>
        p.id === row.id
          ? {
              ...p,
              defaultValue: propertyInlineEditForm.value.defaultValue ?? null,
              description: propertyInlineEditForm.value.description ?? null,
              length: propertyInlineEditForm.value.length ?? null,
              propertyDataTypeId: propertyInlineEditForm.value.propertyDataTypeId ?? p.propertyDataTypeId,
            }
          : p,
      );
      notify?.success({ message: 'Property updated.' });
      propertyInlineEditingRowId.value = undefined;
    }
    catch (error) {
      notify?.error({ message: 'Failed to update property.' });
      console.error('Failed to update property', error);
    }
  }

  /**
   * Builds the filtered property rows for the currently selected class.
   * @param equipmentClassLinks Equipment-to-class relationship rows used for site filtering.
   * @param equipmentRows Equipment rows used to resolve the active plant filter.
   * @returns A computed list of properties matching the selected class and active filters.
   */
  function filteredPropertyRows(
    equipmentClassLinks: Ref<Array<Isa95EquipmentEquipmentClassDto>>,
    equipmentRows: Ref<Array<Isa95EquipmentDto>>,
  ): ComputedRef<Array<Isa95EquipmentClassPropertyDto>> {
    return computed(() => {
      const classId = selectedClass.value?.id;
      if (classId === undefined) return [];

      let rows = getRowsByClassId(classId);

      rows = applySearchFilter(rows);

      if (plantFilter.value === 'all') return rows;

      return applyPlantFilter(rows, equipmentClassLinks, equipmentRows);
    });
  }

  /**
   * Filters all properties belonging to a specific equipment class.
   * @param classId The ID of the selected equipment class.
   * @returns A list of properties associated with the given class ID.
   */
  function getRowsByClassId(
    classId: number,
  ): Array<Isa95EquipmentClassPropertyDto> {
    return classProperties.value.filter(
      property => property.equipmentClassId === classId,
    );
  }

  /**
   * Applies a text-based search filter to the provided property rows.
   * @param rows The list of property rows to filter.
   * @returns A filtered list of properties matching the search query.
   */
  function applySearchFilter(
    rows: Array<Isa95EquipmentClassPropertyDto>,
  ): Array<Isa95EquipmentClassPropertyDto> {
    const normalized = typeof searchQuery.value === 'string'
      ? searchQuery.value.trim().toLowerCase()
      : '';

    if (normalized.length === 0) return rows;

    return rows.filter(property => matchesSearch(property, normalized));
  }

  /**
   * Determines whether a property matches the given search query.
   * @param property The property to evaluate.
   * @param normalized The normalized (lowercase, trimmed) search string.
   * @returns True if the property matches the search query; otherwise false.
   */
  function matchesSearch(
    property: Isa95EquipmentClassPropertyDto,
    normalized: string,
  ): boolean {
    const dtype
      = propertyDataTypes.value.find(
        dt => dt.id === property.propertyDataTypeId,
      )?.code ?? '';

    return [property.code, property.defaultValue ?? '', dtype]
      .join(' ')
      .toLowerCase()
      .includes(normalized);
  }

  /**
   * Applies plant/site-based filtering to property rows.
   * @param rows The list of property rows to filter.
   * @param equipmentClassLinks Equipment-to-class relationship rows.
   * @param equipmentRows Equipment rows used to resolve site filtering.
   * @returns A filtered list of properties associated with the selected plant.
   */
  function applyPlantFilter(
    rows: Array<Isa95EquipmentClassPropertyDto>,
    equipmentClassLinks: Ref<Array<Isa95EquipmentEquipmentClassDto>>,
    equipmentRows: Ref<Array<Isa95EquipmentDto>>,
  ): Array<Isa95EquipmentClassPropertyDto> {
    const siteEquipmentIds = getSiteEquipmentIds(equipmentRows);
    const linkedClassIds = getLinkedClassIds(equipmentClassLinks, siteEquipmentIds);

    return rows.filter(property =>
      linkedClassIds.has(property.equipmentClassId),
    );
  }

  /**
   * Retrieves the set of equipment IDs belonging to the selected plant.
   * @param equipmentRows All available equipment rows.
   * @returns A set of equipment IDs filtered by the active plant.
   */
  function getSiteEquipmentIds(
    equipmentRows: Ref<Array<Isa95EquipmentDto>>,
  ): Set<number> {
    return new Set(
      equipmentRows.value
        .filter(equipment => equipment.site === plantFilter.value)
        .map(equipment => equipment.id),
    );
  }

  /**
   * Retrieves the set of equipment class IDs linked to the provided equipment IDs.
   * @param equipmentClassLinks Equipment-to-class relationship rows.
   * @param siteEquipmentIds Set of equipment IDs filtered by plant.
   * @returns A set of equipment class IDs associated with the given equipment IDs.
   */
  function getLinkedClassIds(
    equipmentClassLinks: Ref<Array<Isa95EquipmentEquipmentClassDto>>,
    siteEquipmentIds: Set<number>,
  ): Set<number> {
    return new Set(
      equipmentClassLinks.value
        .filter(link => siteEquipmentIds.has(link.equipmentId))
        .map(link => link.equipmentClassId),
    );
  }

  return {
    cancelDelete,
    cancelInlineEdit,
    classRows,
    classTableRows,
    closeCreatedDialog,
    confirmDelete,
    createdCode,
    createdDialogOpen,
    createdId,
    deleteDialogOpen,
    dialogOpen,
    editingId,
    form,
    inlineEditForm,
    inlineEditingRowId,
    isEditing,
    levelOptions,
    load,
    openCreate,
    openEdit,
    pendingDeleteClassCode,
    remove,
    requestDelete,
    saveInlineEdit,
    selectById,
    selectedClassRows,
    startInlineEdit,
    submit,
    submitting,

    cancelPropertyDelete,
    cancelPropertyInlineEdit,
    classProperties,
    closePropertiesView,
    confirmPropertyDelete,
    filteredPropertyRows,
    loadProperties,
    openCreateProperty,
    openEditProperty,
    openPropertiesView,
    pendingDeletePropertyId,
    plantFilter,
    propertiesViewOpen,
    propertyDataTypes,
    propertyDeleteDialogOpen,
    propertyForm,
    propertyInlineEditForm,
    propertyInlineEditingRowId,
    propertyIsEditing,
    propertyEditAllowed,
    propertyPanelOpen,
    relatedPanelOpen,
    resetTabState,
    requestPropertyDelete,
    savePropertyInlineEdit,
    searchQuery,
    selectedClass,
    startPropertyInlineEdit,
    submitProperty,
  } satisfies EquipmentClassStoreState & Record<string, unknown>;
});

import { defineStore } from 'pinia';
import { inject, ref, type Ref } from 'vue';

import { useProfileStore } from '../../../Auth/store/user-auth-store';
import {
  createEquipmentWithDetails as createEquipmentWithDetailsApi,
  deleteEquipment as deleteEquipmentApi,
  getEquipmentClassWithRelations,
  getEquipmentClasses as getEquipmentClassesApi,
  getEquipmentLevels as getEquipmentLevelsApi,
  getEquipmentWithRelations,
  getHierarchyDetailsFlat,
  getParentEquipmentOptions as getParentEquipmentOptionsApi,
  saveEquipmentDetails as saveEquipmentDetailsApi,
  type CreateEquipmentPayload,
  type CreateEquipmentWithDetailsDto,
  type Isa95EquipmentClassDto,
  type Isa95EquipmentClassPropertyDto,
  type Isa95EquipmentDto,
  type Isa95EquipmentEquipmentClassDto,
  type Isa95EquipmentLevelDto,
  type Isa95EquipmentPropertyDto,
  type Isa95ParentEquipmentOptionDto,
  type SaveEquipmentDetailsDto,
} from '../services/api';
import type { EquipmentFormState } from '../types';
import type { Isa95HierarchyFlatRowDto } from '../types/isa95-hierarchy-flat-row-dto';
import { getErrorMessage, normalizeClassProperty, type NotifyService } from '../utils/store-helpers';

export interface EquipmentClassLinkPayload {
  equipmentId: number
  equipmentClassId: number
  site: number
}

export interface EquipmentStoreState {
  createEquipmentLevels: Ref<Array<Isa95EquipmentLevelDto>>
  createOptionsLoading: Ref<boolean>
  createParentOptions: Ref<Array<Isa95ParentEquipmentOptionDto>>
  createPropertiesByClassId: Ref<Record<number, Array<Isa95EquipmentClassPropertyDto>>>
  createRelatedClasses: Ref<Array<Isa95EquipmentClassDto>>
  dialogOpen: Ref<boolean>
  editingId: Ref<number | undefined>
  equipmentRows: Ref<Array<Isa95EquipmentDto>>
  flatRows: Ref<Array<Isa95HierarchyFlatRowDto>>
  flatRowsError: Ref<string | null>
  flatRowsLoading: Ref<boolean>
  form: Ref<EquipmentFormState>
  isEditing: Ref<boolean>
  links: Ref<Array<Isa95EquipmentEquipmentClassDto>>
  loading: Ref<boolean>
  properties: Ref<Array<Isa95EquipmentPropertyDto>>
}

export const useEquipmentStore = defineStore('isa95Equipment', () => {
  const notify = inject<NotifyService>('notify');

  // ── Real API state ────────────────────────────────────────────────────────
  const flatRows = ref<Array<Isa95HierarchyFlatRowDto>>([]);
  const flatRowsLoading = ref(false);
  const flatRowsError = ref<string | null>(null);
  const createOptionsLoading = ref(false);
  const createEquipmentLevels = ref<Array<Isa95EquipmentLevelDto>>([]);
  const createParentOptions = ref<Array<Isa95ParentEquipmentOptionDto>>([]);
  const createRelatedClasses = ref<Array<Isa95EquipmentClassDto>>([]);
  const createPropertiesByClassId = ref<Record<number, Array<Isa95EquipmentClassPropertyDto>>>({});

  /**
   * Loads equipment details along with its related entities for a given equipment ID.
   * @param id - Unique identifier of the equipment to load.
   * @returns
   * A promise that resolves to the equipment DTO with relations if successful,
   * or `undefined` if the loading fails.
   * @remarks
   * In case of an error during the loading process, an error notification is displayed
   * and the function safely returns `undefined` instead of throwing.
   */
  async function loadEquipmentWithRelations(
    id: number,
  ): Promise<Isa95EquipmentDto | undefined> {
    try {
      return await getEquipmentWithRelations(id);
    }
    catch (error) {
      notify?.error({
        message: getErrorMessage(error, 'Failed to load equipment details.'),
      });
      return undefined;
    }
  }

  /**
   * Save equipment details (general info, class links, and properties) in one call.
   * @param id - Equipment ID to save
   * @param payload - SaveEquipmentDetailsDto with fields to update, classes, and properties
   * @returns Updated equipment with all relations if successful, or undefined on error
   */
  async function saveEquipmentDetails(
    id: number,
    payload: SaveEquipmentDetailsDto,
  ): Promise<Isa95EquipmentDto | undefined> {
    try {
      const updated = await saveEquipmentDetailsApi(id, payload);
      if (updated) {
        notify?.success({ message: 'Equipment details saved successfully.' });
      }
      else {
        notify?.error({ message: 'Failed to save equipment details.' });
      }
      return updated;
    }
    catch (error) {
      notify?.error({
        message: error instanceof Error ? error.message : 'Failed to save equipment details.',
      });
      return undefined;
    }
  }

  // ── In-memory CRUD state ──────────────────────────────────────────────────
  const equipmentRows = ref<Array<Isa95EquipmentDto>>([]);
  const links = ref<Array<Isa95EquipmentEquipmentClassDto>>([]);
  const properties = ref<Array<Isa95EquipmentPropertyDto>>([]);
  const loading = ref(false);

  const dialogOpen = ref(false);
  const isEditing = ref(false);
  const editingId = ref<number | undefined>(undefined);

  const form = ref<EquipmentFormState>({
    code: '',
    description: '',
    equipmentLevelId: undefined,
    erpSource: '',
    parentEquipmentId: undefined,
    sapObjId: 1,
    site: '',
  });

  // ── Helpers ───────────────────────────────────────────────────────────────

  /**
   * @returns Next available numeric ID for equipment.
   */
  function nextEquipmentId(): number {
    return Math.max(0, ...equipmentRows.value.map(r => r.id)) + 1;
  }

  /**
   * @returns Next available numeric ID for equipment-class links.
   */
  function nextLinkId(): number {
    return Math.max(0, ...links.value.map(l => l.id)) + 1;
  }

  /**
   * @returns Next available numeric ID for equipment properties.
   */
  function nextPropertyId(): number {
    return Math.max(0, ...properties.value.map(p => p.id)) + 1;
  }

  // ── Real API actions ──────────────────────────────────────────────────────

  /**
   * Loads the flat equipment table from the backend using the current user's plant.
   * Each equipment may appear in multiple rows when joined with multiple classes or properties.
   */
  async function loadEquipment(): Promise<void> {
    const profileStore = useProfileStore();
    const plant = String(profileStore.userAttributes.plant);

    flatRowsLoading.value = true;
    flatRowsError.value = null;

    try {
      const result = await getHierarchyDetailsFlat(plant);
      flatRows.value = Array.isArray(result) ? result : [];
    }
    catch (error) {
      flatRowsError.value = error instanceof Error ? error.message : String(error);
      flatRows.value = [];
      notify?.error({
        message: getErrorMessage(error, 'Failed to load equipment data.'),
      });
    }
    finally {
      flatRowsLoading.value = false;
    }
  }

  /**
   * Loads equipment level options for the create panel.
   */
  async function loadCreateEquipmentLevels(): Promise<void> {
    createOptionsLoading.value = true;
    try {
      createEquipmentLevels.value = await getEquipmentLevelsApi();
    }
    catch (error) {
      createEquipmentLevels.value = [];
      notify?.error({
        message: getErrorMessage(error, 'Failed to load equipment levels.'),
      });
    }
    finally {
      createOptionsLoading.value = false;
    }
  }

  /**
   * Loads valid parent candidates for a given equipment level in the current plant.
   * @param equipmentLevelId - Selected equipment level identifier.
   */
  async function loadCreateParentOptions(equipmentLevelId: number): Promise<void> {
    if (equipmentLevelId <= 0) {
      createParentOptions.value = [];
      return;
    }

    createOptionsLoading.value = true;
    try {
      const profileStore = useProfileStore();
      const parsedPlant = Number.parseInt(String(profileStore.userAttributes.plant), 10);
      const plant = Number.isNaN(parsedPlant) ? 0 : parsedPlant;

      createParentOptions.value = await getParentEquipmentOptionsApi(
        plant,
        equipmentLevelId,
      );
    }
    catch (error) {
      createParentOptions.value = [];
      notify?.error({
        message: getErrorMessage(error, 'Failed to load parent options.'),
      });
    }
    finally {
      createOptionsLoading.value = false;
    }
  }

  /**
   * Loads equipment classes filtered by the selected equipment level.
   * @param equipmentLevelId - Selected equipment level identifier.
   */
  async function loadCreateRelatedClasses(equipmentLevelId?: number): Promise<void> {
    createOptionsLoading.value = true;
    try {
      const allClasses = await getEquipmentClassesApi();
      if (equipmentLevelId === undefined || equipmentLevelId === null || Number.isNaN(equipmentLevelId)) {
        createRelatedClasses.value = allClasses;
        return;
      }

      const matchingClasses = allClasses.filter(c => c.equipmentLevelId === equipmentLevelId);

      // Some backend responses omit equipmentLevelId even when the request is already scoped.
      createRelatedClasses.value = matchingClasses.length > 0
        ? matchingClasses
        : allClasses;
    }
    catch (error) {
      createRelatedClasses.value = [];
      notify?.error({
        message: getErrorMessage(error, 'Failed to load related classes.'),
      });
    }
    finally {
      createOptionsLoading.value = false;
    }
  }

  /**
   * Loads dynamic property definitions for each selected equipment class.
   * @param classIds - Selected equipment class identifiers.
   */
  async function loadCreateClassProperties(classIds: Array<number>): Promise<void> {
    if (classIds.length === 0) {
      createPropertiesByClassId.value = {};
      return;
    }

    createOptionsLoading.value = true;
    try {
      const classDetails = await Promise.all(
        classIds.map(async classId => ({
          classId,
          details: await getEquipmentClassWithRelations(classId),
        })),
      );

      createPropertiesByClassId.value = classDetails.reduce<Record<number, Array<Isa95EquipmentClassPropertyDto>>>(
        (accumulator, entry) => {
          accumulator[entry.classId] = (entry.details?.equipmentClassProperties ?? []).map(property => normalizeClassProperty(property));
          return accumulator;
        },
        {},
      );
    }
    catch (error) {
      createPropertiesByClassId.value = {};
      notify?.error({
        message: getErrorMessage(error, 'Failed to load class properties.'),
      });
    }
    finally {
      createOptionsLoading.value = false;
    }
  }

  /**
   * Initializes create panel metadata using the provided level or the first available level.
   * @param defaultEquipmentLevelId - Optional initial equipment level identifier.
   */
  async function initializeCreatePanel(defaultEquipmentLevelId?: number): Promise<void> {
    await loadCreateEquipmentLevels();

    const fallbackLevelId = createEquipmentLevels.value[0]?.id ?? 0;
    const selectedLevelId = defaultEquipmentLevelId ?? fallbackLevelId;
    if (selectedLevelId <= 0) {
      createParentOptions.value = [];
      createRelatedClasses.value = [];
      createPropertiesByClassId.value = {};
      return;
    }

    await Promise.all([
      loadCreateParentOptions(selectedLevelId),
      loadCreateRelatedClasses(selectedLevelId),
    ]);
  }

  /**
   * Creates equipment with related classes and dynamic properties in one request.
   * @param payload - Create payload from the equipment create panel.
   * @returns Created equipment with relations when successful, otherwise undefined.
   */
  async function createEquipmentWithDetails(
    payload: CreateEquipmentWithDetailsDto,
  ): Promise<Isa95EquipmentDto | undefined> {
    const description = (payload.description ?? '').trim();
    const generatedCode = description.length > 0
      ? description.split(/\s+/).join('_')
      : 'NEW_EQUIPMENT';

    const profileStore = useProfileStore();
    const parsedPlant = Number.parseInt(String(profileStore.userAttributes.plant), 10);
    const fallbackPlant = Number.isNaN(parsedPlant) ? 0 : parsedPlant;
    const trimmedCode = payload.code?.trim();
    const resolvedCode = trimmedCode !== undefined && trimmedCode.length > 0
      ? trimmedCode
      : generatedCode;

    const requestPayload: CreateEquipmentWithDetailsDto = {
      ...payload,
      code: resolvedCode,
      description,
      erpSource: payload.erpSource ?? '',
      plant: payload.plant ?? fallbackPlant,
      sapObjId: payload.sapObjId ?? 1,
    };

    try {
      const created = await createEquipmentWithDetailsApi(requestPayload);
      if (created) {
        notify?.success({ message: 'Equipment created successfully.' });
      }
      else {
        notify?.error({ message: 'Failed to create equipment.' });
      }
      return created;
    }
    catch (error) {
      notify?.error({
        message: getErrorMessage(error, 'Failed to create equipment.'),
      });
      return undefined;
    }
  }

  /**
   * Initialises the equipment properties collection.
   */
  function loadProperties(): void {
    properties.value = [];
  }

  /**
   * Opens the equipment creation dialog and initializes the form.
   * @param defaults - Optional partial form values to pre-fill the dialog.
   */
  function openCreate(defaults?: Partial<EquipmentFormState>): void {
    isEditing.value = false;
    editingId.value = undefined;
    form.value = {
      code: '',
      description: '',
      equipmentLevelId: defaults?.equipmentLevelId ?? undefined,
      erpSource: '',
      parentEquipmentId: defaults?.parentEquipmentId ?? undefined,
      sapObjId: 1,
      site: defaults?.site ?? '',
    };
    dialogOpen.value = true;
  }

  /**
   * Opens the equipment edit dialog and maps the selected row into the form state.
   * @param row - Equipment row to populate into the edit form.
   */
  function openEdit(row: Isa95EquipmentDto): void {
    isEditing.value = true;
    editingId.value = row.id;
    form.value = {
      code: row.code,
      description: row.description,
      equipmentLevelId: row.equipmentLevelId,
      erpSource: row.erpSource,
      parentEquipmentId: row.parentEquipmentId ?? undefined,
      sapObjId: row.sapObjId,
      site: row.site,
    };
    dialogOpen.value = true;
  }

  /**
   * Validates the current form and creates or updates the equipment record in-memory.
   * @returns True when the save succeeds, false otherwise.
   */
  function submit(): boolean {
    const requiredFieldsValid
      = form.value.site.length > 0
        && form.value.code.length > 0
        && form.value.equipmentLevelId !== undefined;

    if (!requiredFieldsValid) {
      notify?.warning({ message: 'Site, Code and Level are required.' });
      return false;
    }

    const payload: CreateEquipmentPayload = {
      code: form.value.code.trim(),
      description: form.value.description.trim(),
      equipmentLevelId: Number(form.value.equipmentLevelId),
      erpSource: form.value.erpSource.trim(),
      sapObjId: Number(form.value.sapObjId),
      site: form.value.site.trim(),
    };

    if (form.value.parentEquipmentId !== undefined) {
      payload.parentEquipmentId = Number(form.value.parentEquipmentId);
    }

    try {
      if (isEditing.value && editingId.value !== undefined) {
        const id = editingId.value;
        equipmentRows.value = equipmentRows.value.map(r =>
          r.id === id ? { ...r, ...payload } : r,
        );
        notify?.success({ message: 'Equipment updated.' });
      }
      else {
        const created: Isa95EquipmentDto = {
          id: nextEquipmentId(),
          site: payload.site,
          code: payload.code,
          description: payload.description,
          sapObjId: payload.sapObjId,
          equipmentLevelId: payload.equipmentLevelId,
          parentEquipmentId: payload.parentEquipmentId ?? null,
          erpSource: payload.erpSource,
        };
        equipmentRows.value = [...equipmentRows.value, created];
        notify?.success({ message: 'Equipment created.' });
      }
      dialogOpen.value = false;
      return true;
    }
    catch (error) {
      notify?.error({
        message: getErrorMessage(error, 'Failed to save equipment.'),
      });
      return false;
    }
  }

  /**
   * Removes an equipment record and its related links and properties.
   * @param id - ID of the equipment record to delete.
   * @returns True when deletion succeeds, false otherwise.
   */
  async function remove(id: number): Promise<boolean> {
    try {
      await deleteEquipmentApi(id);
      equipmentRows.value = equipmentRows.value.filter(r => r.id !== id);
      flatRows.value = flatRows.value.filter(row => row.id !== id);
      links.value = links.value.filter(l => l.equipmentId !== id);
      properties.value = properties.value.filter(p => p.equipmentId !== id);
      notify?.success({ message: 'Equipment deleted.' });
      return true;
    }
    catch (error) {
      notify?.error({
        message: getErrorMessage(error, 'Failed to delete equipment.'),
      });
      return false;
    }
  }

  /**
   * Creates a link between an equipment record and an equipment class if it does not already exist.
   * @param payload - Identifiers required to create the class link.
   */
  function addEquipmentClassLink(payload: EquipmentClassLinkPayload): void {
    const alreadyLinked = links.value.some(
      l =>
        l.equipmentId === payload.equipmentId
        && l.equipmentClassId === payload.equipmentClassId,
    );

    if (!alreadyLinked) {
      links.value = [
        ...links.value,
        {
          id: nextLinkId(),
          equipmentId: payload.equipmentId,
          equipmentClassId: payload.equipmentClassId,
          site: payload.site,
        },
      ];
    }
  }

  /**
   * Removes the link between an equipment record and an equipment class.
   * @param payload - Identifiers required to delete the class link.
   */
  function removeEquipmentClassLink(payload: EquipmentClassLinkPayload): void {
    links.value = links.value.filter(
      l =>
        !(
          l.equipmentId === payload.equipmentId
          && l.equipmentClassId === payload.equipmentClassId
        ),
    );
  }

  /**
   * Links an equipment record to an equipment class.
   * @param payload - Identifiers required to create the class link.
   */
  function linkEquipmentClass(payload: EquipmentClassLinkPayload): void {
    addEquipmentClassLink(payload);
  }

  /**
   * Unlinks an equipment record from an equipment class.
   * @param payload - Identifiers required to delete the class link.
   */
  function unlinkEquipmentClass(payload: EquipmentClassLinkPayload): void {
    removeEquipmentClassLink(payload);
  }

  /**
   * Persists property values for an equipment record (merges if record already exists).
   * @param equipmentId - ID of the equipment whose properties are being saved.
   * @param site - Site associated with the property record.
   * @param propertiesJson - Serialized property values keyed by property code.
   */
  function savePropertyValues(
    equipmentId: number,
    site: string,
    propertiesJson: Record<string, unknown>,
  ): void {
    const existing = properties.value.find(p => p.equipmentId === equipmentId);
    if (existing) {
      existing.propertiesJson = { ...existing.propertiesJson, ...propertiesJson };
    }
    else {
      properties.value = [
        ...properties.value,
        {
          id: nextPropertyId(),
          equipmentId,
          equipmentClassId: equipmentId,
          site,
          propertiesJson,
        },
      ];
    }
  }

  /**
   * Replaces all equipment-class links for a given class with a new set of equipment IDs.
   * @param equipmentClassId - The class whose links are being replaced.
   * @param equipmentIds - New set of equipment IDs to link.
   */
  function updateRelatedEquipments(equipmentClassId: number, equipmentIds: Array<number>): void {
    const otherLinks = links.value.filter(l => l.equipmentClassId !== equipmentClassId);
    const newLinks = equipmentIds.map((equipmentId, index) => ({
      id: nextLinkId() + index,
      equipmentId,
      equipmentClassId,
      site: 1,
    }));
    links.value = [...otherLinks, ...newLinks];
  }

  return {
    dialogOpen,
    editingId,
    equipmentRows,
    flatRows,
    flatRowsError,
    flatRowsLoading,
    createEquipmentLevels,
    createOptionsLoading,
    createParentOptions,
    createPropertiesByClassId,
    createRelatedClasses,
    form,
    isEditing,
    links,
    loading,
    loadEquipment,
    loadEquipmentWithRelations,
    createEquipmentWithDetails,
    initializeCreatePanel,
    loadCreateClassProperties,
    loadCreateEquipmentLevels,
    loadCreateParentOptions,
    loadCreateRelatedClasses,
    saveEquipmentDetails,
    loadProperties,
    openCreate,
    openEdit,
    properties,
    remove,
    savePropertyValues,
    submit,
    linkEquipmentClass,
    unlinkEquipmentClass,
    updateRelatedEquipments,
  } satisfies EquipmentStoreState & {
    loadEquipment: () => Promise<void>
    loadEquipmentWithRelations: (id: number) => Promise<Isa95EquipmentDto | undefined>
    createEquipmentWithDetails: (payload: CreateEquipmentWithDetailsDto) => Promise<Isa95EquipmentDto | undefined>
    initializeCreatePanel: (defaultEquipmentLevelId?: number) => Promise<void>
    loadCreateClassProperties: (classIds: Array<number>) => Promise<void>
    loadCreateEquipmentLevels: () => Promise<void>
    loadCreateParentOptions: (equipmentLevelId: number) => Promise<void>
    loadCreateRelatedClasses: (equipmentLevelId?: number) => Promise<void>
    saveEquipmentDetails: (id: number, payload: SaveEquipmentDetailsDto) => Promise<Isa95EquipmentDto | undefined>
    loadProperties: () => void
    openCreate: (defaults?: Partial<EquipmentFormState>) => void
    openEdit: (row: Isa95EquipmentDto) => void
    remove: (id: number) => Promise<boolean>
    savePropertyValues: (equipmentId: number, site: string, propertiesJson: Record<string, unknown>) => void
    submit: () => boolean
    linkEquipmentClass: (payload: EquipmentClassLinkPayload) => void
    unlinkEquipmentClass: (payload: EquipmentClassLinkPayload) => void
    updateRelatedEquipments: (equipmentClassId: number, equipmentIds: Array<number>) => void
  };
});

import { defineStore } from 'pinia';
import { computed, inject, ref } from 'vue';
import { useProfileStore } from '../../../Auth/store/user-auth-store';
import { getRestrictedHierarchyDescriptions } from '../services/api';
import type { Isa95HierarchyDescriptionNodeDto } from '../types/isa95-hierarchy-description-node-dto';
import type { TreeNode } from '../types/tree-node';
import { getErrorMessage, type NotifyService } from '../utils/store-helpers';

const LEVEL_ICONS: Record<string, string> = {
  site: 'factory',
  area: 'corporate_fare',
  line: 'view_stream',
  wc: 'lan',
  res: 'memory',
  cell: 'grid_view',
};

/**
 * Resolve icon name by ISA-95 level code.
 * @param levelCode - The ISA-95 level code
 * @returns The Material Symbol icon name for the given level
 */
function getNodeIcon(levelCode: string): string {
  return LEVEL_ICONS[levelCode.toLowerCase()] ?? 'device_hub';
}

/**
 * Filter tree nodes recursively while preserving matching ancestors.
 * @param nodes - Array of tree nodes to filter
 * @param query - Search query string
 * @returns Filtered array of tree nodes that match the query
 */
function filterTree(nodes: Array<TreeNode>, query: string): Array<TreeNode> {
  const normalized = query.trim().toLowerCase();
  if (normalized.length === 0) return nodes;

  return nodes
    .map((node) => {
      const children = filterTree(node.children, normalized);
      const match = [node.code, node.description, node.levelCode]
        .join(' ')
        .toLowerCase()
        .includes(normalized);

      return match || children.length > 0 ? { ...node, children } : undefined;
    })
    .filter((entry): entry is TreeNode => entry !== undefined);
}

/**
 * Count all nodes in the tree recursively.
 * @param nodes - Array of tree nodes to count
 * @returns Total count of all nodes including descendants
 */
function flattenCount(nodes: Array<TreeNode>): number {
  let count = 0;

  const visit = (items: Array<TreeNode>) => {
    for (const item of items) {
      count += 1;
      if (item.children.length > 0) visit(item.children);
    }
  };

  visit(nodes);
  return count;
}

/**
 * Get all node IDs that belong to the active branch (expanded nodes and all their ancestors).
 * @param nodes - Array of tree nodes
 * @param expanded - Array of currently expanded node IDs
 * @returns Set of active branch node IDs
 */
function getActiveBranchNodes(nodes: Array<TreeNode>, expanded: Array<string>): Set<string> {
  const activeBranch = new Set<string>();

  const visit = (items: Array<TreeNode>, ancestors: Array<string> = []): void => {
    for (const item of items) {
      if (expanded.includes(item.id)) {
        for (const ancestor of ancestors) {
          activeBranch.add(ancestor);
        }
        activeBranch.add(item.id);
      }
      if (item.children.length > 0) {
        visit(item.children, [...ancestors, item.id]);
      }
    }
  };

  visit(nodes);
  return activeBranch;
}

/**
 * Map an array of description DTOs to TreeNodes under a given level code.
 * @param nodes - Array of hierarchy description DTOs
 * @param levelCode - The ISA-95 level code to assign to the mapped nodes
 * @returns Array of mapped TreeNode objects
 */
function mapChildren(
  nodes: Array<Isa95HierarchyDescriptionNodeDto>,
  levelCode: string,
): Array<TreeNode> {
  return nodes.map(node => mapNodeToTreeNode(node, levelCode));
}

/**
 * Map a single hierarchy description DTO to a TreeNode.
 * @param node - Hierarchy description DTO from the backend
 * @param levelCode - The ISA-95 level code to assign to this node
 * @returns A TreeNode ready for use in the q-tree component
 */
function mapNodeToTreeNode(
  node: Isa95HierarchyDescriptionNodeDto,
  levelCode: string,
): TreeNode {
  const children: Array<TreeNode> = [
    ...mapChildren(node.area ?? [], 'area'),
    ...mapChildren(node.productionLine ?? [], 'line'),
    ...mapChildren(node.workCenter ?? [], 'wc'),
    ...mapChildren(node.workUnit ?? [], 'res'),
  ];

  return {
    id: node.code,
    code: node.code,
    label: node.displayLabel,
    description: node.description,
    levelCode,
    children,
  };
}

/**
 * Collect node IDs to auto-expand up to a given depth.
 * @param nodes - Array of tree nodes
 * @param depth - Current recursion depth
 * @param maxDepth - Maximum depth to expand
 * @returns Array of node IDs that should be expanded
 */
function collectExpandedIds(nodes: Array<TreeNode>, depth: number, maxDepth: number): Array<string> {
  if (depth >= maxDepth) return [];
  const ids: Array<string> = [];
  for (const node of nodes) {
    if (node.children.length > 0) {
      ids.push(node.id, ...collectExpandedIds(node.children, depth + 1, maxDepth));
    }
  }
  return ids;
}

/**
 * Collect node IDs that should be expanded to reveal matching search results.
 * Expands any node that matches the query or has matching descendants.
 * @param nodes - Array of tree nodes
 * @param query - Search query string
 * @param expanded - Set to accumulate expanded node IDs
 * @returns true if this node or any descendant matches
 */
function collectSearchExpandedIds(
  nodes: Array<TreeNode>,
  query: string,
  expanded = new Set<string>(),
): Set<string> {
  const normalized = query.trim().toLowerCase();
  if (normalized.length === 0) return expanded;

  const collect = (items: Array<TreeNode>): boolean => {
    let hasMatch = false;
    for (const node of items) {
      const nodeMatches = [node.code, node.description, node.levelCode]
        .join(' ')
        .toLowerCase()
        .includes(normalized);

      const childrenHaveMatches = node.children.length > 0 && collect(node.children);

      if (nodeMatches || childrenHaveMatches) {
        expanded.add(node.id);
        hasMatch = true;
      }
    }
    return hasMatch;
  };

  collect(nodes);
  return expanded;
}

export const useHierarchyStore = defineStore('isa95Hierarchy', () => {
  const notify = inject<NotifyService>('notify');
  const hierarchy = ref<Array<TreeNode>>([]);
  const searchQuery = ref('');
  const expanded = ref<Array<string>>([]);
  const selectedNodeId = ref<string | undefined>(undefined);
  const isLoading = ref(false);
  const loadError = ref<string | null>(null);
  const selectedNodeForFilter = ref<TreeNode | null>(null);

  const visibleTree = computed(() => filterTree(hierarchy.value, searchQuery.value));
  const hierarchyCount = computed(() => flattenCount(visibleTree.value));
  const activeBranch = computed(() => getActiveBranchNodes(hierarchy.value, expanded.value));

  /**
   *
   */
  async function loadHierarchy(): Promise<void> {
    const userAttributesStore = useProfileStore();
    const plant = String(userAttributesStore.userAttributes.plant);

    isLoading.value = true;
    loadError.value = null;

    try {
      const nodes = await getRestrictedHierarchyDescriptions(plant);
      hierarchy.value = nodes.map(node => mapNodeToTreeNode(node, 'site'));
      expanded.value = collectExpandedIds(hierarchy.value, 0, Infinity);
    }
    catch (error) {
      const message = getErrorMessage(error, 'Failed to load hierarchy data.');
      loadError.value = message;
      hierarchy.value = [];
      notify?.error({ message });
    }
    finally {
      isLoading.value = false;
    }
  }

  /**
   * Get all node IDs in the hierarchy.
   * @returns Array of all node IDs
   */
  function getAllHierarchyNodeIds(): Array<string> {
    return collectExpandedIds(hierarchy.value, 0, Infinity);
  }

  /**
   * Get node IDs that should be expanded to reveal search results.
   * @param query - Search query string
   * @returns Array of node IDs to expand
   */
  function getSearchExpandedIds(query: string): Array<string> {
    return [...collectSearchExpandedIds(hierarchy.value, query)];
  }

  /**
   * Set the selected node for equipment filtering.
   * @param node - The tree node to use as a filter
   */
  function setSelectedNodeForFilter(node: TreeNode): void {
    selectedNodeForFilter.value = node;
  }

  /**
   * Clear the selected node filter.
   */
  function clearSelectedNodeForFilter(): void {
    selectedNodeForFilter.value = null;
  }

  return {
    activeBranch,
    clearSelectedNodeForFilter,
    expanded,
    getAllHierarchyNodeIds,
    getNodeIcon,
    getSearchExpandedIds,
    hierarchy,
    hierarchyCount,
    isLoading,
    loadError,
    loadHierarchy,
    searchQuery,
    selectedNodeForFilter,
    selectedNodeId,
    setSelectedNodeForFilter,
    visibleTree,
  };
});

