export type PropertyDataTypeKind = 'boolean' | 'date' | 'list' | 'number' | 'string';

/**
 * Normalizes a string array by trimming whitespace and filtering empty strings.
 * @param values - The array of strings to normalize
 * @returns Array of trimmed, non-empty strings
 */
function normalizeStringArray(values: Array<string>): Array<string> {
  return values
    .map(item => item.trim())
    .filter(item => item.length > 0);
}

/**
 * Returns unique normalized values from a string array.
 * @param values - The array of strings to deduplicate
 * @returns Array of unique normalized strings
 */
export function normalizeUniqueValues(values: Array<string>): Array<string> {
  return Array.from(new Set(normalizeStringArray(values)));
}

/**
 * Converts an array of strings to a comma-delimited string.
 * @param values - The array of strings to join
 * @returns Comma-delimited string or undefined if no values
 */
export function toDelimitedString(values: Array<string>): string | undefined {
  const normalizedValues = normalizeUniqueValues(values);
  return normalizedValues.length > 0 ? normalizedValues.join(',') : undefined;
}

/**
 * Resolves the data type kind from property code or type ID.
 * @param code - The property code to analyze
 * @param propertyDataTypeId - The property data type ID
 * @returns The resolved property data type kind
 */
export function resolvePropertyDataTypeKind(
  code: string | undefined,
  propertyDataTypeId?: number | null,
): PropertyDataTypeKind | undefined {
  const normalizedCode = code?.toUpperCase();
  const normalizedPropertyDataTypeId = propertyDataTypeId === undefined || propertyDataTypeId === null
    ? undefined
    : Number(propertyDataTypeId);

  if (normalizedPropertyDataTypeId === 1) {
    return 'boolean';
  }

  if (normalizedPropertyDataTypeId === 2) {
    return 'date';
  }

  if (normalizedPropertyDataTypeId === 3) {
    return 'list';
  }

  if (normalizedCode === undefined) {
    return undefined;
  }

  if (normalizedCode.includes('BOOL')) {
    return 'boolean';
  }

  if (normalizedCode.includes('DATE') || normalizedCode.includes('TIME')) {
    return 'date';
  }

  if (normalizedCode.includes('LIST') || normalizedCode.includes('ENUM')) {
    return 'list';
  }

  if (
    normalizedCode.includes('NUMBER')
    || normalizedCode.includes('NUMERIC')
    || normalizedCode.includes('INT')
    || normalizedCode.includes('DEC')
    || normalizedCode.includes('FLOAT')
    || normalizedCode.includes('DOUBLE')
  ) {
    return 'number';
  }

  return 'string';
}

/**
 * Gets the data type kind of a property.
 * @param property - The equipment class property
 * @returns The property data type kind
 */
export function getPropertyDataTypeKind(
  property: Isa95EquipmentClassPropertyDto,
): PropertyDataTypeKind {
  return resolvePropertyDataTypeKind(
    property.propertyDataTypeCode ?? property.propertyDataType?.code,
    property.propertyDataTypeId,
  ) ?? 'string';
}

/**
 * Gets the display priority for property editor ordering.
 * @param property - The equipment class property
 * @returns Numeric priority for sorting (lower = earlier)
 */
function getPropertyEditorDisplayPriority(
  property: Isa95EquipmentClassPropertyDto,
): number {
  switch (getPropertyDataTypeKind(property)) {
    case 'list': {
      return 0;
    }
    case 'string':
    case 'number': {
      return 1;
    }
    case 'date': {
      return 2;
    }
    case 'boolean': {
      return 3;
    }
    default: {
      return 4;
    }
  }
}

/**
 * Converts supported primitive-like values into a comparable string.
 * @param value - The value to normalize for string comparison
 * @returns Comparable string representation or empty string for unsupported values
 */
function toComparableStringValue(value: unknown): string {
  if (typeof value === 'string') {
    return value;
  }

  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') {
    return String(value);
  }

  if (value instanceof Date) {
    return value.toISOString();
  }

  return '';
}

/**
 * Sorts properties by editor display priority (list → text/number → date → boolean).
 * @param properties - The array of properties to sort
 * @returns New array of sorted properties
 */
export function sortPropertiesByEditorDisplay(
  properties: Array<Isa95EquipmentClassPropertyDto>,
): Array<Isa95EquipmentClassPropertyDto> {
  const buckets: Array<Array<Isa95EquipmentClassPropertyDto>> = [[], [], [], [], []];

  for (const property of properties) {
    const priority = getPropertyEditorDisplayPriority(property);
    if (priority === 0) {
      buckets[0].push(property);
      continue;
    }

    if (priority === 1) {
      buckets[1].push(property);
      continue;
    }

    if (priority === 2) {
      buckets[2].push(property);
      continue;
    }

    if (priority === 3) {
      buckets[3].push(property);
      continue;
    }

    buckets[4].push(property);
  }

  return buckets.flat();
}

/**
 * Checks if a class property is locked (read-only for ClassType).
 * @param property - The equipment class property
 * @returns True if property is locked
 */
export function isClassPropertyLocked(property: Isa95EquipmentClassPropertyDto): boolean {
  return property.classPropertyType === 'ClassType';
}

/**
 * Parses allowed values from various string formats.
 * @param value - The allowed values (array, comma-delimited string, or null)
 * @returns Array of parsed allowed values
 */
export function parseAllowedValues(value: Array<string> | string | null | undefined): Array<string> {
  if (Array.isArray(value)) {
    return normalizeStringArray(value);
  }

  return normalizeStringArray((value ?? '').split(','));
}

/**
 * Gets legacy allowed values from the property semantics JSON.
 * @param semanticsJson The property semantics JSON object.
 * @returns The allowed values as an array, string, null, or undefined.
 */
function getLegacyAllowedValues(
  semanticsJson: Isa95EquipmentClassPropertyDto['propertySemanticsJson'],
): Array<string> | string | null | undefined {
  if (semanticsJson === null || semanticsJson === undefined || typeof semanticsJson !== 'object') {
    return undefined;
  }

  const legacyAllowedValues = (semanticsJson as Record<string, unknown>).allowed_values;
  if (typeof legacyAllowedValues === 'string' || Array.isArray(legacyAllowedValues)) {
    return legacyAllowedValues;
  }

  return undefined;
}

/**
 * Gets the allowed value options for a property.
 * @param property - The equipment class property
 * @returns Array of allowed values
 */
export function getAllowedValueOptions(property: Isa95EquipmentClassPropertyDto): Array<string> {
  const semanticsJson = property.propertySemanticsJson;
  const allowedValuesSource = property.allowedValues
    ?? property.propertySemanticsJson?.allowedValues
    ?? getLegacyAllowedValues(semanticsJson);
  return parseAllowedValues(allowedValuesSource);
}

/**
 * Checks if a property is a multi-select list.
 * @param property - The equipment class property
 * @returns True if property is multi-select list
 */
export function isMultiSelectList(property: Isa95EquipmentClassPropertyDto): boolean {
  return getPropertyDataTypeKind(property) === 'list' && property.cardinality === 'array';
}

/**
 * Coerces a value to the correct type for a property.
 * @param property - The equipment class property
 * @param value - The value to coerce
 * @returns Coerced value of appropriate type
 */
function coercePropertyValue(
  property: Isa95EquipmentClassPropertyDto,
  value: unknown,
): unknown {
  const kind = getPropertyDataTypeKind(property);

  if (kind === 'boolean') {
    if (typeof value === 'boolean') {
      return value;
    }

    if (typeof value === 'string') {
      return value.trim().toLowerCase() === 'true';
    }

    if (typeof value === 'number') {
      return value !== 0;
    }

    return false;
  }

  if (value === null || value === undefined) {
    return '';
  }

  if (typeof value === 'number') {
    return String(value);
  }

  if (typeof value === 'string') {
    return value;
  }

  return toComparableStringValue(value);
}

/**
 * Gets the semantic initial value for a class property.
 * @param property - The equipment class property
 * @returns The semantic initial value or undefined
 */
function getSemanticInitialValue(property: Isa95EquipmentClassPropertyDto): unknown {
  if (property.classPropertyType === 'InstanceType') {
    return undefined;
  }

  return property.defaultValue ?? undefined;
}

/**
 * Gets the initial value for a property considering existing or default values.
 * @param property - The equipment class property
 * @param existingValue - The existing property value if any
 * @returns The coerced initial value
 */
export function getInitialPropertyValue(
  property: Isa95EquipmentClassPropertyDto,
  existingValue: unknown,
): unknown {
  const sourceValue = existingValue ?? getSemanticInitialValue(property);
  const coercedValue = coercePropertyValue(property, sourceValue);

  // For list properties, normalize the value to match allowed values exactly
  const kind = getPropertyDataTypeKind(property);
  if (kind === 'list' && typeof coercedValue === 'string') {
    // Get allowed values from either property field or semantics JSON
    const semanticsJson = property.propertySemanticsJson;
    const allowedValuesSource = property.allowedValues
      ?? property.propertySemanticsJson?.allowedValues
      ?? getLegacyAllowedValues(semanticsJson);
    const allowedValues = parseAllowedValues(allowedValuesSource);

    if (allowedValues.length > 0) {
      const valueItems = parseAllowedValues(coercedValue);

      // For multi-select, join all items; for single-select, use first item
      if (property.cardinality === 'array') {
        return valueItems.filter(item => allowedValues.includes(item)).join(',') || coercedValue;
      }
      else {
        const matched = valueItems.find(item => allowedValues.includes(item));
        return matched ?? coercedValue;
      }
    }
  }

  return coercedValue;
}

/**
 * Converts a value to a boolean.
 * @param value - The value to convert
 * @returns Boolean representation of the value
 */
export function toBooleanValue(value: unknown): boolean {
  if (typeof value === 'boolean') {
    return value;
  }

  if (typeof value === 'string') {
    return value.trim().toLowerCase() === 'true';
  }

  if (typeof value === 'number') {
    return value !== 0;
  }

  return false;
}

/**
 * Converts a value to string for input fields.
 * @param value - The value to convert
 * @returns String representation for input display
 */
export function toInputValue(value: unknown): string {
  if (typeof value === 'string') {
    return value;
  }
  if (typeof value === 'number') {
    return String(value);
  }
  return '';
}

/**
 * Converts a value to a single select option string.
 * @param value - The value to convert
 * @returns Select value or null
 */
export function toSelectValue(value: unknown): string | null {
  if (typeof value === 'string' && value.length > 0) {
    const normalized = parseAllowedValues(value);
    return normalized.length > 0 ? normalized[0] : null;
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      if (typeof item === 'string' && item.length > 0) {
        return item.trim();
      }
    }
  }
  return null;
}

/**
 * Converts a value to multi-select option strings.
 * @param value - The value to convert
 * @returns Array of select values
 */
export function toMultiSelectValue(value: unknown): Array<string> {
  if (Array.isArray(value)) {
    return normalizeStringArray(
      value.filter((item): item is string => typeof item === 'string'),
    );
  }

  if (typeof value === 'string') {
    return parseAllowedValues(value);
  }

  return [];
}

/**
 * Converts a value to ISO-like datetime format.
 * @param value - The value to convert
 * @returns Formatted datetime string (YYYY-MM-DDTHH:mm)
 */
export function toDateTimeValue(value: unknown): string {
  if (typeof value !== 'string' || value.trim().length === 0) {
    return '';
  }

  const trimmedValue = value.trim();
  const date = new Date(trimmedValue);

  if (Number.isNaN(date.getTime())) {
    return trimmedValue.slice(0, 16);
  }

  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');

  return `${year}-${month}-${day}T${hours}:${minutes}`;
}

/**
 * Converts a value to Quasar datetime format.
 * @param value - The value to convert
 * @returns Formatted datetime string for Quasar (YYYY-MM-DD HH:mm)
 */
export function toQuasarDateTimeValue(value: unknown): string {
  const normalized = toDateTimeValue(value);
  return normalized.length > 0 ? normalized.replace('T', ' ') : '';
}

/**
 * Converts Quasar datetime format to ISO-like format.
 * @param value - The Quasar datetime string to convert
 * @returns ISO-like datetime string (YYYY-MM-DDTHH:mm)
 */
export function fromQuasarDateTimeValue(value: string): string {
  return value.trim().length > 0 ? value.replace(' ', 'T') : '';
}

export const SQL_IDENTIFIER_MAX_LENGTH = 128;

const SQL_IDENTIFIER_PATTERN = /^[A-Z_a-z]\w*$/;

/**
 * @param value  value to validate
 * @param label  label for the value
 * @returns validation message if invalid, empty string if valid
 */
export function getSqlIdentifierValidationMessage(
  value: string,
  label: string,
): string {
  const normalizedValue = value.trim();

  if (normalizedValue.length === 0) {
    return '';
  }

  if (normalizedValue.length > SQL_IDENTIFIER_MAX_LENGTH) {
    return `${label} must be ${SQL_IDENTIFIER_MAX_LENGTH} characters or fewer.`;
  }

  if (!SQL_IDENTIFIER_PATTERN.test(normalizedValue)) {
    return `${label} must start with a letter or underscore and use only letters, numbers, and underscores. Prefer camelCase, for example: myCode.`;
  }

  return '';
}

/**
 * @param value  value to validate
 * @returns true if value is a valid SQL identifier, false otherwise
 */
export function isValidSqlIdentifier(value: string): boolean {
  return (
    value.trim().length > 0
    && getSqlIdentifierValidationMessage(value, 'Value') === ''
  );
}

import type { Isa95EquipmentClassPropertyDto } from '../types';

/**
 * Notification service contract used by ISA-95 stores.
 */
export interface NotifyService {
  success: (options: { title?: string, message: string }) => void
  error: (options: { title?: string, message: string }) => void
  warning: (options: { title?: string, message: string }) => void
}

/**
 * Safely reads response data from an unknown error shape.
 * @param error Unknown thrown error.
 * @returns Raw response payload when present.
 */
function getResponseData(error: unknown): unknown {
  return (error as { response?: { data?: unknown } })?.response?.data;
}

/**
 * Returns a trimmed string value when non-empty.
 * @param value Value to normalize.
 * @returns Non-empty string or null.
 */
function asNonEmptyString(value: unknown): string | null {
  if (typeof value !== 'string') {
    return null;
  }

  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

/**
 * Joins string arrays into a comma-separated, non-empty message.
 * @param value Candidate array value.
 * @returns Rendered message or null.
 */
function getRenderedStringArray(value: unknown): string | null {
  if (!Array.isArray(value)) {
    return null;
  }

  const rendered = value
    .filter((item): item is string => typeof item === 'string')
    .map(item => item.trim())
    .filter(item => item.length > 0)
    .join(', ');

  return rendered.length > 0 ? rendered : null;
}

/**
 * Attempts to parse a JSON string and extract a nested message.
 * @param value Raw string payload.
 * @returns Parsed nested message when available, otherwise null.
 */
function getParsedJsonMessage(value: string): string | null {
  try {
    const parsed = JSON.parse(value) as { message?: unknown };
    return asNonEmptyString(parsed.message);
  }
  catch {
    return null;
  }
}

/**
 * Extracts a backend message from object-like response payloads.
 * @param responseData Response payload to inspect.
 * @returns Best message extracted from backend structure, or null.
 */
function getObjectResponseMessage(responseData: unknown): string | null {
  if (responseData === null || typeof responseData !== 'object') {
    return null;
  }

  const payload = responseData as Record<string, unknown>;

  // Messages[] array is the primary backend error format.
  const messages = getRenderedStringArray(payload.messages);
  if (messages !== null) {
    return messages;
  }

  // Message / error / detail are scalar fallback fields.
  const directMessage = payload.message ?? payload.error ?? payload.detail;

  const renderedArrayMessage = getRenderedStringArray(directMessage);
  if (renderedArrayMessage !== null) {
    return renderedArrayMessage;
  }

  const directString = asNonEmptyString(directMessage);
  if (directString === null) {
    return null;
  }

  return getParsedJsonMessage(directString) ?? directString;
}

/**
 * Extracts a user-facing message from API/runtime errors.
 * Supports backend envelopes that use `messages[]` (array), `message` (string),
 * `error`, or `detail` fields, as well as plain Error instances.
 * @param error Unknown thrown error.
 * @param fallback Fallback message when no specific message is available.
 * @returns Best available error message.
 */
export function getErrorMessage(error: unknown, fallback: string): string {
  const responseData = getResponseData(error);

  const stringResponse = asNonEmptyString(responseData);
  if (stringResponse !== null) {
    return stringResponse;
  }

  const objectMessage = getObjectResponseMessage(responseData);
  if (objectMessage !== null) {
    return objectMessage;
  }

  const errorMessage = asNonEmptyString(error instanceof Error ? error.message : undefined);
  return errorMessage ?? fallback;
}

/**
 * Gets a semantic string value from semantics object by checking multiple keys.
 * @param semantics - The semantics object to search
 * @param keys - Keys to check in order
 * @returns The first non-empty string value found, or null
 */
function getSemanticStringValue(
  semantics: Record<string, unknown> | null | undefined,
  ...keys: Array<string>
): string | null {
  if (semantics === null || semantics === undefined) {
    return null;
  }

  const semanticEntries = Object.entries(semantics);

  for (const key of keys) {
    const value = semanticEntries.find(([entryKey]) => entryKey === key)?.[1];
    if (typeof value === 'string' && value.trim().length > 0) {
      return value;
    }
  }

  return null;
}

/**
 * Converts allowed values to a normalized unique string array.
 * @param value - The allowed values (array or other type)
 * @returns Array of unique normalized strings, or null if invalid
 */
function getAllowedValuesArray(
  value: unknown,
): Array<string> | null {
  if (Array.isArray(value)) {
    const normalizedValues = value
      .filter((item): item is string => typeof item === 'string')
      .map(item => item.trim())
      .filter(item => item.length > 0);

    return normalizedValues.length > 0
      ? Array.from(new Set(normalizedValues))
      : null;
  }

  return null;
}

/**
 * Normalizes a class property by extracting semantic values and allowed values.
 * @param property - The class property to normalize
 * @returns Normalized class property with extracted semantics and allowed values
 */
export function normalizeClassProperty(
  property: Isa95EquipmentClassPropertyDto,
): Isa95EquipmentClassPropertyDto {
  const semantics = property.propertySemanticsJson as Record<string, unknown> | null | undefined;
  const resolvedPropertyDataTypeCode
    = property.propertyDataTypeCode ?? property.propertyDataType?.code ?? null;

  return {
    ...property,
    propertyDataTypeCode: resolvedPropertyDataTypeCode,
    propertyDataType: resolvedPropertyDataTypeCode === null
      ? property.propertyDataType ?? null
      : {
          code: resolvedPropertyDataTypeCode,
          id: property.propertyDataType?.id ?? property.propertyDataTypeId,
        },
    cardinality: getSemanticStringValue(semantics, 'cardinality') ?? property.cardinality ?? null,
    classPropertyType: getSemanticStringValue(
      semantics,
      'class_property_type',
      'classPropertyType',
    ) ?? property.classPropertyType ?? null,
    defaultValue: getSemanticStringValue(
      semantics,
      'default_value',
      'defaultValue',
    ) ?? property.defaultValue ?? null,
    allowedValues: getAllowedValuesArray(property.allowedValues)
      ?? getAllowedValuesArray(semantics?.allowed_values)
      ?? getAllowedValuesArray(semantics?.allowedValues)
      ?? null,
  };
}

