/**
 * Formats raw date-like values for table display.
 * @param value The raw value to normalize into a YYYY-MM-DD string.
 * @returns The normalized date string or a placeholder when unavailable.
 */
function formatDateDisplayValue(
  value: string | number | boolean | undefined | null,
): string {
  if (typeof value !== 'string' && typeof value !== 'number') {
    return '-';
  }

  const normalizedValue = String(value).trim();
  if (normalizedValue.length === 0) return '-';

  const directIsoMatch = /^(\d{4}-\d{2}-\d{2})/.exec(normalizedValue);
  if (directIsoMatch !== null) {
    return directIsoMatch[1];
  }

  const parsed = new Date(normalizedValue);
  if (Number.isNaN(parsed.getTime())) {
    return normalizedValue;
  }

  return parsed.toISOString().slice(0, 10);
}

