/**
 * Resolves the class property type from the supported semantics payload shapes.
 * @param semantics The semantics payload returned by the backend.
 * @returns The resolved class property type when present.
 */
function resolvePropertySemanticsClassPropertyType(
  semantics: PhysicalAssetClassPropertySemanticsApiDto | null | undefined,
): string | null | undefined {
  const rawSemantics = semantics as RawPhysicalAssetClassPropertySemanticsApiDto
    | null
    | undefined;
  const classPropertyType = semantics?.classPropertyType
    ?? rawSemantics?.class_property_type;

  return typeof classPropertyType === 'string' || classPropertyType === null
    ? classPropertyType
    : undefined;
}

/**
 * Resolves the default value from the supported semantics payload shapes.
 * @param semantics The semantics payload returned by the backend.
 * @returns The resolved default value when present.
 */
function resolvePropertySemanticsDefaultValue(
  semantics: PhysicalAssetClassPropertySemanticsApiDto | null | undefined,
): unknown {
  const rawSemantics = semantics as RawPhysicalAssetClassPropertySemanticsApiDto
    | null
    | undefined;

  return semantics?.defaultValue ?? rawSemantics?.default_value;
}

/**
 * Resolves allowed values from supported semantics payload shapes.
 * @param semantics The semantics payload returned by the backend.
 * @returns The raw allowed-values payload when present.
 */
function resolvePropertySemanticsAllowedValues(
  semantics: PhysicalAssetClassPropertySemanticsApiDto | null | undefined,
): unknown {
  const rawSemantics = semantics as RawPhysicalAssetClassPropertySemanticsApiDto
    | null
    | undefined;

  return semantics?.allowedValues ?? rawSemantics?.allowed_values;
}

/**
 * Converts a scalar-like API value to the UI's nullable string shape.
 * @param value Raw value from direct fields or semantics JSON.
 * @returns String value, null, or undefined when absent.
 */
function toNullableStringValue(value: unknown): string | null | undefined {
  if (value === undefined) {
    return undefined;
  }

  if (value === null) {
    return null;
  }

  if (Array.isArray(value)) {
    const rendered = value.map(String).join(',');
    return rendered.length > 0 ? rendered : null;
  }

  if (
    typeof value === 'string'
    || typeof value === 'number'
    || typeof value === 'boolean'
  ) {
    return String(value);
  }

  return undefined;
}

/**
 * Resolves the property semantics object across legacy and current field names.
 * @param property The class-property payload returned by the backend.
 * @returns The normalized semantics object when present.
 */
function resolvePhysicalAssetClassPropertySemantics(
  property: PhysicalAssetClassPropertyApiDto,
): PhysicalAssetClassPropertySemanticsApiDto | null | undefined {
  return property.propertySemanticsJson ?? property.semanticsJson;
}

/**
 * Extracts an array from either a plain array response or an envelope payload.
 * @template T
 * @param payload The backend payload to normalize.
 * @returns The extracted array of items.
 */
export function extractArrayData<T>(
  payload: PhysicalAssetArrayPayload<T> | undefined,
): Array<T> {
  if (Array.isArray(payload)) {
    return payload;
  }

  if (payload !== null && payload !== undefined && Array.isArray(payload.data)) {
    return payload.data;
  }

  if (
    payload !== null
    && payload !== undefined
    && 'rows' in payload
  ) {
    const rows = payload.rows;
    if (Array.isArray(rows)) {
      return rows;
    }
  }

  return [];
}

/**
 * Extracts the best available class description, preferring the explicit field and English locale.
 * @param physicalAssetClass The class payload to inspect.
 * @returns The resolved description when available.
 */
function extractPhysicalAssetClassDescription(
  physicalAssetClass: PhysicalAssetClassApiDto | null | undefined,
): string | undefined {
  const englishDescription = physicalAssetClass?.descriptions?.find(
    description => description.code === 'EN',
  )?.description;
  const fallbackDescription = physicalAssetClass?.descriptions?.[0]?.description;

  return physicalAssetClass?.description ?? englishDescription ?? fallbackDescription;
}

/**
 * Resolves a class parent identifier while normalizing missing values to `null`.
 * @param source The source object containing the parent class identifier.
 * @param source.id The physical asset class identifier used to match inheritance links.
 * @param source.parentPhysicalAssetClassId The parent class identifier.
 * @param source.parentInheritances The inheritance links returned on the parent-inheritance relation.
 * @param source.childInheritances The inheritance links returned on the child-inheritance relation.
 * @returns The normalized parent class identifier.
 */
function resolveParentPhysicalAssetClassId(source: {
  id?: number
  parentPhysicalAssetClassId?: number | null
  parentInheritances?: Array<PhysicalAssetClassInheritanceApiDto> | null
  childInheritances?: Array<PhysicalAssetClassInheritanceApiDto> | null
}): number | null {
  if (source.parentPhysicalAssetClassId !== undefined) {
    return source.parentPhysicalAssetClassId ?? null;
  }

  const currentClassId = source.id;
  const resolvedInheritance = [
    ...(source.childInheritances ?? []),
    ...(source.parentInheritances ?? []),
  ].find(
    inheritance =>
      currentClassId !== undefined
      && (
        inheritance.childPhysicalAssetClassId === currentClassId
        || inheritance.childPhysicalAssetClass?.id === currentClassId
      ),
  );

  if (resolvedInheritance === undefined) {
    return null;
  }

  return resolvedInheritance.parentPhysicalAssetClassId
    ?? resolvedInheritance.parentPhysicalAssetClass?.id
    ?? null;
}

/**
 * Resolves a physical asset class identifier while normalizing missing values to `0`.
 * @param source The source object containing the class identifier.
 * @param source.physicalAssetClassId The class identifier.
 * @returns The normalized class identifier.
 */
function resolvePhysicalAssetClassId(source: {
  physicalAssetClassId?: number | null
}): number {
  return source.physicalAssetClassId ?? 0;
}

/**
 * Reads the class property count from a class payload when provided.
 * @param source The source object containing the property count.
 * @param source.physicalAssetClassPropertiesCount The class property count.
 * @returns The number of class properties, if present.
 */
function resolvePhysicalAssetClassPropertiesCount(source: {
  physicalAssetClassPropertiesCount?: number
}): number | undefined {
  return source.physicalAssetClassPropertiesCount;
}

/**
 * Reads the linked physical asset count from a class payload when provided.
 * @param source The source object containing the class-to-asset links.
 * @param source.physicalAssetClassPhysicalAssets The physical asset links for the class.
 * @returns The number of linked physical assets, if present.
 */
function resolveLinkedPhysicalAssetsCount(source: {
  physicalAssetClassPhysicalAssets?: Array<PhysicalAssetClassAssignmentApiDto> | null
}): number | undefined {
  if (source.physicalAssetClassPhysicalAssets === undefined) {
    return undefined;
  }

  return source.physicalAssetClassPhysicalAssets?.length ?? 0;
}

/**
 * Resolves a parent class property identifier while normalizing missing values to `null`.
 * @param source The source object containing the parent property identifier.
 * @param source.parentPhysicalAssetClassPropertyId The parent class property identifier.
 * @returns The normalized parent property identifier.
 */
function resolveParentPhysicalAssetClassPropertyId(source: {
  parentPhysicalAssetClassPropertyId?: number | null
}): number | null {
  return source.parentPhysicalAssetClassPropertyId ?? null;
}

/**
 * Resolves and maps an embedded physical asset class definition.
 * @param source The source object containing the optional class definition.
 * @returns The mapped class definition when available.
 */
function resolvePhysicalAssetClassDefinition(source: {
  physicalAssetClass?: PhysicalAssetClassApiDto | null
} | null | undefined): Isa95PhysicalAssetClassDto | undefined {
  if (source == null) {
    return undefined;
  }

  return mapPhysicalAssetClass(source.physicalAssetClass);
}

/**
 * Maps a physical asset class API payload into the UI DTO shape.
 * @param physicalAssetClass The class payload to map.
 * @returns The mapped class DTO when the payload is defined.
 */
export function mapPhysicalAssetClass(
  physicalAssetClass: PhysicalAssetClassApiDto | null | undefined,
): Isa95PhysicalAssetClassDto | undefined {
  if (physicalAssetClass == null) {
    return undefined;
  }

  return {
    id: physicalAssetClass.id,
    code: physicalAssetClass.code,
    description: extractPhysicalAssetClassDescription(physicalAssetClass),
    parentPhysicalAssetClassId: resolveParentPhysicalAssetClassId(physicalAssetClass),
    isCustom: physicalAssetClass.isCustom,
    linkedPhysicalAssetsCount: resolveLinkedPhysicalAssetsCount(physicalAssetClass),
    physicalAssetClassPropertiesCount: resolvePhysicalAssetClassPropertiesCount(
      physicalAssetClass,
    ),
  };
}

/**
 * Resolves the numeric physical asset identifier from the supported API shapes.
 * @param source The source object containing either `id` or `physicalAssetId`.
 * @param source.id The direct identifier candidate.
 * @param source.physicalAssetId The nested physical asset identifier candidate.
 * @returns The resolved numeric identifier when parsing succeeds.
 */
function resolvePhysicalAssetId(source: {
  id?: number | string
  physicalAssetId?: number | string
}): number | undefined {
  for (const candidate of [source.id, source.physicalAssetId]) {
    if (typeof candidate === 'number' && Number.isFinite(candidate)) {
      return candidate;
    }

    if (typeof candidate === 'string') {
      const normalized = Number.parseInt(candidate, 10);
      if (Number.isFinite(normalized)) {
        return normalized;
      }
    }
  }

  return undefined;
}

/**
 * Maps a localized physical asset description payload into the UI DTO shape.
 * @param description The description payload to map.
