      toNullableStringValue(property.defaultValue)
      ?? toNullableStringValue(resolvePropertySemanticsDefaultValue(propertySemantics))
      ?? null,
    allowedValues:
      toNullableStringValue(property.allowedValues)
      ?? toNullableStringValue(resolvePropertySemanticsAllowedValues(propertySemantics))
      ?? null,
    length: property.length,
    scale: property.scale,
