/**
 * Finds the primary description to expose for a physical asset flat-row view.
 * @param physicalAsset The physical asset payload to inspect.
 * @returns The resolved language code and description.
 */
function findPrimaryPhysicalAssetDescription(
  physicalAsset: PhysicalAssetApiDto,
): ResolvedPhysicalAssetDescription {
  const descriptions = physicalAsset.descriptions ?? [];
  const englishDescription = descriptions.find(description => description.code === 'EN');
  const fallbackDescription = descriptions[0];
  const resolvedDescription = englishDescription ?? fallbackDescription;

  return {
    code: resolvedDescription?.code ?? null,
    description: resolvedDescription?.description ?? physicalAsset.description ?? null,
  };
}

/**
 * Determines whether a physical asset payload is already a flat-row response.
 * @param row The payload to inspect.
 * @returns Whether the payload matches the flat-row API shape.
 */
export function isPhysicalAssetFlatRow(
  row: PhysicalAssetApiDto | PhysicalAssetFlatRowApiDto,
): row is PhysicalAssetFlatRowApiDto {
  return 'classCode' in row || 'descriptionByLanguage' in row || 'propertiesJson' in row;
}

/**
 * Maps a collection of child physical assets while preserving cyclic reference protection.
 * @param children The child assets to map.
 * @param seen The cache of already mapped assets.
 * @returns The mapped child assets when provided.
 */
function mapPhysicalAssetChildren(
  children: Array<PhysicalAssetApiDto> | null | undefined,
  seen: WeakMap<PhysicalAssetApiDto, Isa95PhysicalAssetDto>,
): Array<Isa95PhysicalAssetDto> | undefined {
  if (children == null) {
    return undefined;
  }

  const mappedChildren: Array<Isa95PhysicalAssetDto> = [];

  for (const child of children) {
    const mappedChild = mapPhysicalAsset(child, seen);
    if (mappedChild !== undefined) {
      mappedChildren.push(mappedChild);
    }
  }

  return mappedChildren;
}

/**
 * Resolves the primary class and property relations used by list views.
 * @param physicalAsset The physical asset payload to inspect.
 * @returns The primary related class definition, class identifier, and property.
 */
function resolvePrimaryPhysicalAssetRelations(
  physicalAsset: PhysicalAssetApiDto,
): PrimaryPhysicalAssetRelations {
  const primaryClassRelation = physicalAsset.physicalAssetClassPhysicalAssets?.[0];
  const primaryProperty = physicalAsset.physicalAssetProperties?.[0];
  const primaryClassSource = primaryClassRelation ?? primaryProperty;
  const classId = primaryClassSource
    ? resolvePhysicalAssetClassId(primaryClassSource)
    : null;

  return {
    classDefinition: resolvePhysicalAssetClassDefinition(primaryClassSource),
    classId,
    property: primaryProperty,
  };
}

/**
 * Maps a physical asset API payload into the UI DTO shape while preserving object identity.
 * @param physicalAsset The physical asset payload to map.
 * @param seen The cache used to prevent infinite recursion across cyclic graphs.
 * @returns The mapped physical asset DTO when the payload is valid.
 */
export function mapPhysicalAsset(
  physicalAsset: PhysicalAssetApiDto | null | undefined,
  seen: WeakMap<PhysicalAssetApiDto, Isa95PhysicalAssetDto>
    = new WeakMap<PhysicalAssetApiDto, Isa95PhysicalAssetDto>(),
): Isa95PhysicalAssetDto | undefined {
  if (physicalAsset == null) {
    return undefined;
  }

  const cachedAsset = seen.get(physicalAsset);
  if (cachedAsset !== undefined) {
    return cachedAsset;
  }

  const physicalAssetId = resolvePhysicalAssetId(physicalAsset);
  if (physicalAssetId === undefined) {
    return undefined;
  }

  const mappedAsset: Isa95PhysicalAssetDto = {
    id: physicalAssetId,
    site: String(physicalAsset.site ?? physicalAsset.plant ?? ''),
    plant: physicalAsset.plant ?? physicalAsset.site,
    code: physicalAsset.code,
    description: physicalAsset.description,
    effectiveEndDate: physicalAsset.effectiveEndDate ?? null,
    effectiveStartDate: physicalAsset.effectiveStartDate ?? null,
    physicalAssetLocation: physicalAsset.physicalAssetLocation ?? null,
    sapObjId: physicalAsset.sapObjId,
    parentPhysicalAssetId: physicalAsset.parentPhysicalAssetId ?? null,
    erpSource: physicalAsset.erpSource,
  };

  seen.set(physicalAsset, mappedAsset);

  const parentPhysicalAsset = physicalAsset.parentPhysicalAsset;
  if (parentPhysicalAsset != null) {
    mappedAsset.parentPhysicalAsset = mapPhysicalAsset(parentPhysicalAsset, seen);
  }

  const mappedChildren = mapPhysicalAssetChildren(physicalAsset.children, seen);
  if (mappedChildren !== undefined) {
    mappedAsset.children = mappedChildren;
  }

  if (physicalAsset.descriptions != null) {
    mappedAsset.descriptions = physicalAsset.descriptions.map(
      description => mapPhysicalAssetDescription(description),
    );
  }

  const physicalAssetClassAssignments = physicalAsset.physicalAssetClassPhysicalAssets;
  if (physicalAssetClassAssignments != null) {
    mappedAsset.physicalAssetClassAssignments = physicalAssetClassAssignments.map(
      assignment => mapPhysicalAssetClassAssignment(assignment),
    );
  }

  const physicalAssetProperties = physicalAsset.physicalAssetProperties;
  if (physicalAssetProperties != null) {
    mappedAsset.physicalAssetProperties = physicalAssetProperties.map(
      property => mapPhysicalAssetProperty(property),
    );
  }

  return mappedAsset;
}

/**
 * Maps a flat-row physical asset API payload into the UI DTO shape.
 * @param row The flat-row payload to map.
 * @returns The mapped flat-row DTO when the payload contains a valid identifier.
 */
export function mapPhysicalAssetFlatRow(
  row: PhysicalAssetFlatRowApiDto,
): Isa95PhysicalAssetFlatRowDto | undefined {
  const physicalAssetId = resolvePhysicalAssetId(row);
  if (physicalAssetId === undefined) {
    return undefined;
  }

  return {
    classCode: row.classCode,
    classId: row.classId,
    classIsCustom: row.classIsCustom,
    code: row.code,
    descriptionByLanguage: row.descriptionByLanguage,
    descriptionLanguageCode: row.descriptionLanguageCode,
    effectiveEndDate: row.effectiveEndDate ?? null,
    effectiveStartDate: row.effectiveStartDate ?? null,
    erpSource: row.erpSource,
    id: physicalAssetId,
    parentPhysicalAssetId: row.parentPhysicalAssetId ?? null,
    physicalAssetLocation: row.physicalAssetLocation ?? null,
    plant: String(row.plant),
    propertiesJson: row.propertiesJson,
    propertyId: row.propertyId,
    sapObjId: row.sapObjId,
  };
}

/**
 * Maps a hierarchical physical asset list item into the flat-row DTO shape.
 * @param physicalAsset The physical asset payload to map.
 * @returns The mapped flat-row DTO when the payload contains a valid identifier.
 */
export function mapPhysicalAssetListItemToFlatRow(
  physicalAsset: PhysicalAssetApiDto,
): Isa95PhysicalAssetFlatRowDto | undefined {
  const physicalAssetId = resolvePhysicalAssetId(physicalAsset);
  if (physicalAssetId === undefined) {
    return undefined;
  }

  const primaryRelations = resolvePrimaryPhysicalAssetRelations(physicalAsset);
  const description = findPrimaryPhysicalAssetDescription(physicalAsset);

  return {
    classCode: primaryRelations.classDefinition?.code ?? null,
    classId: primaryRelations.classId,
    classIsCustom: primaryRelations.classDefinition?.isCustom ?? null,
    code: physicalAsset.code,
    descriptionByLanguage: description.description,
    descriptionLanguageCode: description.code,
    effectiveEndDate: physicalAsset.effectiveEndDate ?? null,
    effectiveStartDate: physicalAsset.effectiveStartDate ?? null,
    erpSource: physicalAsset.erpSource,
    id: physicalAssetId,
    parentPhysicalAssetId: physicalAsset.parentPhysicalAssetId ?? null,
    physicalAssetLocation: physicalAsset.physicalAssetLocation ?? null,
    plant: String(physicalAsset.plant ?? physicalAsset.site ?? ''),
    propertiesJson: primaryRelations.property?.propertiesJson ?? null,
    propertyId: primaryRelations.property?.id ?? null,
    sapObjId: physicalAsset.sapObjId,
  };
}

/**
 * Maps class property values from the save-details DTO to the backend payload shape.
 * @param payload The class property entries provided by the UI.
 * @returns The normalized class property payload for the backend.
 */
function mapClassPropertiesPayload(
  payload: SavePhysicalAssetDetailsDto['classProperties'],
): SavePhysicalAssetDetailsApiDto['classProperties'] {
  return payload?.flatMap((entry) => {
    const physicalAssetClassId = entry.physicalAssetClassId;

    if (!Number.isFinite(physicalAssetClassId) || physicalAssetClassId <= 0) {
      return [];
    }

    const mappedEntry: NonNullable<SavePhysicalAssetDetailsApiDto['classProperties']>[number] = {
      physicalAssetClassId,
      properties: entry.properties,
    };

    return [mappedEntry];
  });
}

/**
 * Trims an optional string and omits it when it becomes empty.
 * @param value The string value to normalize.
 * @returns The trimmed string, or `undefined` when empty.
 */
function resolveOptionalTrimmedString(
  value: string | null | undefined,
): string | undefined {
  const normalizedValue = value?.trim();

  return normalizedValue !== undefined && normalizedValue.length > 0
    ? normalizedValue
    : undefined;
}

/**
 * Maps the save-details UI DTO into the backend payload shape.
 * @param payload The save-details payload provided by the UI.
 * @returns The normalized backend payload.
 */
export function mapSavePhysicalAssetDetailsPayload(
  payload: SavePhysicalAssetDetailsDto,
): SavePhysicalAssetDetailsApiDto {
  const normalizedDescription = payload.description === undefined
    ? undefined
    : payload.description.trim();

  return {
    code: resolveOptionalTrimmedString(payload.code),
    description: normalizedDescription,
    ...(payload.effectiveEndDate === undefined
      ? {}
      : { effectiveEndDate: payload.effectiveEndDate }),
    ...(payload.effectiveStartDate === undefined
      ? {}
      : { effectiveStartDate: payload.effectiveStartDate }),
    parentPhysicalAssetId: payload.parentPhysicalAssetId,
    ...(payload.physicalAssetLocation === undefined
      ? {}
      : { physicalAssetLocation: payload.physicalAssetLocation }),
    erpSource: resolveOptionalTrimmedString(payload.erpSource),
    classIds: payload.classIds,
    classProperties: mapClassPropertiesPayload(payload.classProperties),
    properties: payload.properties,
    propertiesPhysicalAssetClassId: payload.propertiesPhysicalAssetClassId,
  };
}

/**
 * Maps a class property create/update payload into the backend request body.
 * @param payload The class property payload to map.
 * @returns The backend request body.
 */
export function mapPhysicalAssetClassPropertyPayload(
  payload: CreatePhysicalAssetClassPropertyPayload,
): Record<string, unknown> {
  return {
    code: payload.code.trim(),
    description: payload.description,
    descriptionCode: payload.descriptionCode,
    physicalAssetClassId: payload.physicalAssetClassId,
    length: payload.length,
    parentPhysicalAssetClassPropertyId:
      payload.parentPhysicalAssetClassPropertyId,
    propertyDataTypeId: payload.propertyDataTypeId,
    propertySemanticsJson: payload.propertySemanticsJson,
    scale: payload.scale,
  };
}

