/**
 * Builds authorization headers for hierarchy backend requests.
 * @returns The authorization headers when a token is available.
 */
function authHeaders(): Record<string, string> {
  return buildBearerAuthHeaders(token);
}

/**
 * Performs a PUT request using the same wrapped-response rules as the shared HTTP helpers.
 * @param url Request URL.
 * @param payload Body payload sent with the request.
 * @param fallback Default message used when no server message is available.
 * @param config Optional axios request configuration.
 * @returns Response body typed as T.
 */
async function requestPut<T>(
  url: string,
  payload: unknown,
  fallback: string,
  config?: AxiosRequestConfig,
): Promise<WrappedResponse<T>> {
  let response;

  try {
    response = await axiosLib.put<WrappedResponse<T>>(url, payload, config);
  }
  catch (error) {
    throw new Error(extractErrorReason(error, fallback));
  }

  if (!isWrappedResponse<T>(response.data)) {
    throw new Error(extractBackendMessage(response.data) ?? fallback);
  }

  return response.data;
}

/**
 * Sends a single physical asset details save request to the backend.
 * @param id The physical asset identifier to update.
 * @param payload The physical asset details payload to persist.
 * @returns The raw backend response for the save operation.
 */
async function patchPhysicalAssetDetails(
  id: number,
  payload: SavePhysicalAssetDetailsDto,
): Promise<PhysicalAssetApiDto | undefined> {
  const body = await requestPatch<PhysicalAssetApiDto | null>(
    `${physicalAssetUrl}/${id}/save-details`,
    mapSavePhysicalAssetDetailsPayload(payload),
    'Failed to save physical asset details.',
    {
      headers: authHeaders(),
    },
  );

  return unwrapPayload(body);
}

/**
 * Fetches the property data types used by physical asset class properties.
 * Property data types are served from the shared setup backend equipment-model controller.
 * @returns The list of available property data types.
 */
export async function getPropertyDataTypes(): Promise<Array<Isa95PropertyDataTypeDto>> {
  const response = await axiosLib.get<
    PropertyDataTypesPayload | WrappedResponse<PropertyDataTypesPayload>
  >(
    `${equipmentApiBase}/property-data-types`,
    {
      headers: authHeaders(),
    },
  );

  const payload = isWrappedResponse<PropertyDataTypesPayload>(response.data)
    ? unwrapPayload(response.data)
    : response.data;

  return extractArrayData(payload);
}

/**
 * Fetches the flat physical asset rows for the selected plant.
 * @param plant The active plant code.
 * @returns The flat physical asset rows for the requested plant.
 */
export async function getPhysicalAssetDetailsFlat(
  plant: string,
): Promise<Array<Isa95PhysicalAssetFlatRowDto>> {
  const body = await requestGet<PhysicalAssetFlatPayload>(
    `${apiBase}/getPhysicalAssetDetailsFlat`,
    'Failed to load physical asset details.',
    {
      headers: authHeaders(),
      params: {
        plant,
      },
