 * Saves physical asset details and refreshes the latest relations afterward.
 * @param id The physical asset identifier to update.
 * @param payload The physical asset details payload to save.
 * @returns The refreshed physical asset details after the save completes.
 */
export async function savePhysicalAssetDetails(
  id: number,
  payload: SavePhysicalAssetDetailsDto,
): Promise<Isa95PhysicalAssetDto | undefined> {
  const normalizedClassIds = payload.classIds === undefined
    ? undefined
    : [...new Set(
        payload.classIds.filter(
          classId => Number.isFinite(classId) && classId > 0,
        ),
      )];
  const normalizedClassProperties = (payload.classProperties ?? []).filter(
    classProperty =>
      Number.isFinite(classProperty.physicalAssetClassId)
      && classProperty.physicalAssetClassId > 0,
  );

  await patchPhysicalAssetDetails(id, {
    ...payload,
    classIds: normalizedClassIds,
    classProperties:
      normalizedClassProperties.length === 0
        ? undefined
        : normalizedClassProperties,
  });

  return await getPhysicalAssetWithRelations(id);
}

import { defineStore } from 'pinia';
import { inject, ref, type Ref } from 'vue';

import { useProfileStore } from '../../../Auth/store/user-auth-store';
import {
  createPhysicalAssetWithDetails as createPhysicalAssetWithDetailsApi,
  deletePhysicalAsset as deletePhysicalAssetApi,
  getPhysicalAssetDetailsFlat,
  getPhysicalAssetClasses,
  getPhysicalAssetClassWithRelations,
  getPhysicalAssetWithRelations,
  savePhysicalAssetDetails as savePhysicalAssetDetailsApi,
  type CreatePhysicalAssetWithDetailsDto,
  type Isa95PhysicalAssetClassDto,
  type Isa95PhysicalAssetClassPropertyDto,
  type Isa95PhysicalAssetDto,
  type SavePhysicalAssetDetailsDto,
} from '../services/api';
import type { Isa95PhysicalAssetFlatRowDto } from '../types/isa95-physical-asset-flat-row-dto';
import { getErrorMessage, type NotifyService } from '../utils/store-helpers';

export interface PhysicalAssetStoreState {
  createOptionsLoading: Ref<boolean>
  createPropertiesByClassId: Ref<Record<number, Array<Isa95PhysicalAssetClassPropertyDto>>>
  createRelatedClasses: Ref<Array<Isa95PhysicalAssetClassDto>>
  flatRows: Ref<Array<Isa95PhysicalAssetFlatRowDto>>
  flatRowsError: Ref<string | null>
  flatRowsLoading: Ref<boolean>
}

export const usePhysicalAssetStore = defineStore('isa95PhysicalAssetModel', () => {
  const notify = inject<NotifyService>('notify');

  const createOptionsLoading = ref(false);
  const createPropertiesByClassId = ref<Record<number, Array<Isa95PhysicalAssetClassPropertyDto>>>({});
  const createRelatedClasses = ref<Array<Isa95PhysicalAssetClassDto>>([]);
  const flatRows = ref<Array<Isa95PhysicalAssetFlatRowDto>>([]);
  const flatRowsLoading = ref(false);
  const flatRowsError = ref<string | null>(null);

  /** Loads the class options available for physical asset editing. */
  async function loadCreateRelatedClasses(): Promise<void> {
    createOptionsLoading.value = true;

    try {
      createRelatedClasses.value = await getPhysicalAssetClasses();
    }
    catch (error) {
      createRelatedClasses.value = [];
      notify?.error({
        message: getErrorMessage(error, 'Failed to load physical asset classes.'),
      });
    }
    finally {
      createOptionsLoading.value = false;
    }
  }

  /**
   * Loads property definitions for the selected physical asset classes.
   * @param classIds The selected physical asset class identifiers.
   */
  async function loadCreateClassProperties(classIds: Array<number>): Promise<void> {
    const validClassIds = [...new Set(
      classIds.filter(classId => Number.isFinite(classId) && classId > 0),
    )];

    if (validClassIds.length === 0) {
      createPropertiesByClassId.value = {};
      return;
    }

    createOptionsLoading.value = true;

    try {
      const classDetails: Array<{
        classId: number
        details: Isa95PhysicalAssetClassDto | undefined
      }> = await Promise.all(
        validClassIds.map(async classId => ({
          classId,
          details: await getPhysicalAssetClassWithRelations(classId),
        })),
      );

      createPropertiesByClassId.value = classDetails.reduce<Record<number, Array<Isa95PhysicalAssetClassPropertyDto>>>(
        (accumulator, entry) => {
          accumulator[entry.classId] = entry.details?.physicalAssetClassProperties ?? [];
          return accumulator;
        },
        {},
      );
    }
    catch (error) {
      createPropertiesByClassId.value = {};
      notify?.error({
        message: getErrorMessage(error, 'Failed to load physical asset class properties.'),
      });
    }
    finally {
      createOptionsLoading.value = false;
    }
  }

  /** Loads the flat physical asset rows for the active plant. */
  async function loadPhysicalAssets(): Promise<void> {
    const profileStore = useProfileStore();
    const plant = String(profileStore.userAttributes.plant);

    flatRowsLoading.value = true;
    flatRowsError.value = null;

    try {
      flatRows.value = await getPhysicalAssetDetailsFlat(plant);
    }
    catch (error) {
      flatRowsError.value = error instanceof Error ? error.message : String(error);
      flatRows.value = [];
      notify?.error({
        message: getErrorMessage(error, 'Failed to load physical asset data.'),
      });
    }
    finally {
      flatRowsLoading.value = false;
    }
  }

  /**
   * Creates a physical asset with related classes and dynamic properties.
   * @param payload The create payload from a physical asset create panel.
   * @returns The created physical asset when the request succeeds.
   */
  async function createPhysicalAssetWithDetails(
    payload: CreatePhysicalAssetWithDetailsDto,
  ): Promise<Isa95PhysicalAssetDto | undefined> {
    const profileStore = useProfileStore();
    const parsedPlant = Number.parseInt(String(profileStore.userAttributes.plant), 10);
    const fallbackPlant = Number.isNaN(parsedPlant) ? 0 : parsedPlant;
    const description = (payload.description ?? '').trim();
    const generatedCode = description.length > 0
      ? description.split(/\s+/).join('_')
      : 'NEW_PHYSICAL_ASSET';
    const trimmedCode = payload.code?.trim();

    const requestPayload: CreatePhysicalAssetWithDetailsDto = {
      ...payload,
      code: trimmedCode !== undefined && trimmedCode.length > 0
        ? trimmedCode
        : generatedCode,
      description,
      erpSource: payload.erpSource ?? '',
      plant: payload.plant ?? fallbackPlant,
    };

    try {
      const created = await createPhysicalAssetWithDetailsApi(requestPayload);
      if (created) {
        notify?.success({ message: 'Physical asset created successfully.' });
      }
      else {
        notify?.error({ message: 'Failed to create physical asset.' });
      }

      return created;
    }
    catch (error) {
      notify?.error({
        message: getErrorMessage(error, 'Failed to create physical asset.'),
      });
      return undefined;
    }
  }

  /**
   * Loads a single physical asset with all related entities needed by the details panel.
   * @param id The physical asset identifier.
   * @returns The physical asset details when the request succeeds.
   */
  async function loadPhysicalAssetWithRelations(
    id: number,
  ): Promise<Isa95PhysicalAssetDto | undefined> {
    if (!Number.isFinite(id) || id <= 0) {
      notify?.error({ message: 'Failed to load physical asset details.' });
      return undefined;
    }

    try {
      return await getPhysicalAssetWithRelations(id);
    }
    catch (error) {
      notify?.error({
        message: getErrorMessage(error, 'Failed to load physical asset details.'),
      });
      return undefined;
    }
  }

  /**
   * Persists edits from the physical asset details panel.
   * @param id The physical asset identifier.
   * @param payload The physical asset details payload to save.
   * @returns The updated physical asset when the save succeeds.
   */
  async function savePhysicalAssetDetails(
    id: number,
    payload: SavePhysicalAssetDetailsDto,
  ): Promise<Isa95PhysicalAssetDto | undefined> {
    if (!Number.isFinite(id) || id <= 0) {
      notify?.error({ message: 'Failed to save physical asset details.' });
      return undefined;
    }

    try {
      const updated = await savePhysicalAssetDetailsApi(id, payload);

      if (updated) {
        notify?.success({ message: 'Physical asset details saved successfully.' });
      }
      else {
        notify?.error({ message: 'Failed to save physical asset details.' });
      }

      return updated;
    }
    catch (error) {
      notify?.error({
        message: getErrorMessage(error, 'Failed to save physical asset details.'),
      });
      return undefined;
    }
  }

  /**
   * Deletes a physical asset and removes it from loaded flat rows.
   * @param id The physical asset identifier.
   * @returns True when deletion succeeds.
   */
  async function remove(id: number): Promise<boolean> {
    if (!Number.isFinite(id) || id <= 0) {
      notify?.error({ message: 'Failed to delete physical asset.' });
      return false;
    }

    try {
      await deletePhysicalAssetApi(id);
      flatRows.value = flatRows.value.filter(row => row.id !== id);
      notify?.success({ message: 'Physical asset deleted.' });
      return true;
    }
    catch (error) {
      notify?.error({
        message: getErrorMessage(error, 'Failed to delete physical asset.'),
      });
      return false;
    }
  }

  return {
    createPhysicalAssetWithDetails,
    createOptionsLoading,
    createPropertiesByClassId,
    createRelatedClasses,
    flatRows,
    flatRowsError,
    flatRowsLoading,
    loadCreateClassProperties,
    loadCreateRelatedClasses,
    loadPhysicalAssetWithRelations,
    loadPhysicalAssets,
    remove,
    savePhysicalAssetDetails,
  } satisfies PhysicalAssetStoreState & {
    createPhysicalAssetWithDetails: (payload: CreatePhysicalAssetWithDetailsDto) => Promise<Isa95PhysicalAssetDto | undefined>
    loadCreateClassProperties: (classIds: Array<number>) => Promise<void>
    loadCreateRelatedClasses: () => Promise<void>
    loadPhysicalAssetWithRelations: (id: number) => Promise<Isa95PhysicalAssetDto | undefined>
    loadPhysicalAssets: () => Promise<void>
    remove: (id: number) => Promise<boolean>
    savePhysicalAssetDetails: (id: number, payload: SavePhysicalAssetDetailsDto) => Promise<Isa95PhysicalAssetDto | undefined>
  };
});

