export type PropertyDataTypeKind = 'boolean' | 'date' | 'list' | 'number' | 'string';

/**
 * Resolves the semantic kind for a property data type.
 * @param code The property data type code.
 * @param propertyDataTypeId The numeric property data type identifier.
 * @returns The resolved property data type kind when available.
 */
export function resolvePropertyDataTypeKind(
  code: string | null | undefined,
  propertyDataTypeId?: number | string | null,
): PropertyDataTypeKind | undefined {
  const normalizedCode = code?.trim().toUpperCase();
  const normalizedPropertyDataTypeId = propertyDataTypeId == null
    ? undefined
    : Number(propertyDataTypeId);

  if (normalizedPropertyDataTypeId === 1) {
    return 'boolean';
  }

  if (normalizedPropertyDataTypeId === 2) {
    return 'date';
  }

  if (normalizedPropertyDataTypeId === 3) {
    return 'list';
  }

  if (normalizedCode === undefined || normalizedCode.length === 0) {
    return undefined;
  }

  if (normalizedCode.includes('BOOL')) {
    return 'boolean';
  }

  if (normalizedCode.includes('DATE') || normalizedCode.includes('TIME')) {
    return 'date';
  }

  if (normalizedCode.includes('LIST') || normalizedCode.includes('ENUM')) {
    return 'list';
  }

  if (
    normalizedCode.includes('NUMBER')
    || normalizedCode.includes('NUMERIC')
    || normalizedCode.includes('INT')
    || normalizedCode.includes('DEC')
    || normalizedCode.includes('FLOAT')
    || normalizedCode.includes('DOUBLE')
  ) {
    return 'number';
  }

  return 'string';
}

export const SQL_IDENTIFIER_MAX_LENGTH = 128;

const SQL_IDENTIFIER_PATTERN = /^[A-Z_a-z]\w*$/;

/**
 * @param value  value to validate
 * @param label  label for the value
 * @returns validation message if invalid, empty string if valid
 */
export function getSqlIdentifierValidationMessage(
  value: string,
  label: string,
): string {
  const normalizedValue = value.trim();

  if (normalizedValue.length === 0) {
    return '';
  }

  if (normalizedValue.length > SQL_IDENTIFIER_MAX_LENGTH) {
    return `${label} must be ${SQL_IDENTIFIER_MAX_LENGTH} characters or fewer.`;
  }

  if (!SQL_IDENTIFIER_PATTERN.test(normalizedValue)) {
    return `${label} must start with a letter or underscore and use only letters, numbers, and underscores. Prefer camelCase, for example: myCode.`;
  }

  return '';
}

/**
 * @param value  value to validate
 * @returns true if value is a valid SQL identifier, false otherwise
 */
export function isValidSqlIdentifier(value: string): boolean {
  return (
    value.trim().length > 0
    && getSqlIdentifierValidationMessage(value, 'Value') === ''
  );
}

/**
 * Notification service contract used by ISA-95 physical asset stores.
 */
export interface NotifyService {
  success: (options: { title?: string, message: string }) => void
  error: (options: { title?: string, message: string }) => void
  warning: (options: { title?: string, message: string }) => void
}

/**
 * Safely reads response data from an unknown error shape.
 * @param error Unknown thrown error.
 * @returns Raw response payload when present.
 */
function getResponseData(error: unknown): unknown {
  return (error as { response?: { data?: unknown } })?.response?.data;
}

/**
 * Returns a trimmed string value when non-empty.
 * @param value Value to normalize.
 * @returns Non-empty string or null.
 */
function asNonEmptyString(value: unknown): string | null {
  if (typeof value !== 'string') {
    return null;
  }

  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
}

/**
 * Joins string arrays into a comma-separated, non-empty message.
 * @param value Candidate array value.
 * @returns Rendered message or null.
 */
function getRenderedStringArray(value: unknown): string | null {
  if (!Array.isArray(value)) {
    return null;
  }

  const rendered = value
    .filter((item): item is string => typeof item === 'string')
    .map(item => item.trim())
    .filter(item => item.length > 0)
    .join(', ');

  return rendered.length > 0 ? rendered : null;
}

/**
 * Attempts to parse a JSON string and extract a nested message.
 * @param value Raw string payload.
 * @returns Parsed nested message when available, otherwise null.
 */
function getParsedJsonMessage(value: string): string | null {
  try {
    const parsed = JSON.parse(value) as { message?: unknown };
    return asNonEmptyString(parsed.message);
  }
  catch {
    return null;
  }
}

/**
 * Extracts a backend message from object-like response payloads.
 * @param responseData Response payload to inspect.
 * @returns Best message extracted from backend structure, or null.
 */
function getObjectResponseMessage(responseData: unknown): string | null {
  if (responseData === null || typeof responseData !== 'object') {
    return null;
  }

  const payload = responseData as Record<string, unknown>;

  const messages = getRenderedStringArray(payload.messages);
  if (messages !== null) {
    return messages;
  }

  const directMessage = payload.message ?? payload.error ?? payload.detail;

  const renderedArrayMessage = getRenderedStringArray(directMessage);
  if (renderedArrayMessage !== null) {
    return renderedArrayMessage;
  }

  const directString = asNonEmptyString(directMessage);
  if (directString === null) {
    return null;
  }

  return getParsedJsonMessage(directString) ?? directString;
}

/**
 * Extracts a user-facing message from API/runtime errors.
 * @param error Unknown thrown error.
 * @param fallback Fallback message when no specific message is available.
 * @returns Best available error message.
 */
export function getErrorMessage(error: unknown, fallback: string): string {
  const responseData = getResponseData(error);

  const stringResponse = asNonEmptyString(responseData);
  if (stringResponse !== null) {
    return getParsedJsonMessage(stringResponse) ?? stringResponse;
  }

  const objectMessage = getObjectResponseMessage(responseData);
  if (objectMessage !== null) {
    return objectMessage;
  }

  const errorMessage = asNonEmptyString(error instanceof Error ? error.message : undefined);
  return errorMessage ?? fallback;
}

