/**
 * Formats a given date string into an ISO 8601 string without seconds.
 * @param inNewPicking - The date string to be formatted.
 * @returns The formatted ISO 8601 string.
 */
export function formatDate(inNewPicking: string): string {
  const myDate = new Date(Date.parse(inNewPicking));
  const year = myDate.getFullYear();
  const month = (myDate.getMonth() + 1).toString().padStart(2, '0');
  const day = myDate.getDate().toString().padStart(2, '0');
  const hours = myDate.getHours().toString().padStart(2, '0');
  const minutes = myDate.getMinutes().toString().padStart(2, '0');
  const iso8601String = `${year}-${month}-${day}T${hours}:${minutes}:00`;
  return iso8601String;
}

/**
 * Format code-like values for display.
 * Removes the CUST_ prefix, inserts spaces for camel/snake/kebab case,
 * and uppercases the first visible letter.
 * @param value Raw label value.
 * @returns Human-readable label or '-' when empty.
 */
export function formatDisplayValue(value: string | number | boolean | undefined | null): string {
  if (typeof value !== 'string' && typeof value !== 'number' && typeof value !== 'boolean') {
    return '-';
  }

  const trimmedValue = String(value).trim();
  if (trimmedValue === '') return '-';

  // Strip CUST_ prefix and replace separators with spaces using safe, non-backtracking patterns.
  const withoutPrefix = trimmedValue.replace(/^CUST_/i, '').replace(/[_-]+/g, ' ');

  // Split camelCase without regex to avoid any backtracking risk.
  let spaced = '';
  for (let i = 0; i < withoutPrefix.length; i++) {
    const current = withoutPrefix.charAt(i);
    const previous = withoutPrefix.charAt(i - 1);
    const next = withoutPrefix.charAt(i + 1);
    const isUpper = current >= 'A' && current <= 'Z';
    const previousIsLowerOrDigit = (previous >= 'a' && previous <= 'z') || (previous >= '0' && previous <= '9');
    const previousIsUpper = previous >= 'A' && previous <= 'Z';
    const nextIsLower = next >= 'a' && next <= 'z';

    if (i > 0 && isUpper && (previousIsLowerOrDigit || (previousIsUpper && nextIsLower))) {
      spaced += ' ';
    }
    spaced += current;
  }

  const normalizedValue = spaced.replace(/\s+/g, ' ').trim().toLowerCase();

  if (normalizedValue.length === 0) return '-';

  return normalizedValue.charAt(0).toUpperCase() + normalizedValue.slice(1);
}

